    await testAsync('★ #8 📌 の置き直し・お願いは楽観ロック (updated_at) — 別の運営が先に動かした行を古い画面から上書きしない (実行)', async () => {
        const fnOf = (name) => {
            const body = _client.match(new RegExp(`window\\.${name} = async function[\\s\\S]*?\\n\\};\\n`))?.[0];
            assert.ok(body, `${name} が見つからない`);
            const helpers = ['_isMissingReservationTable', '_isMissingPinCols'].map(h => _client.match(new RegExp(`function ${h}\\(error\\) \\{[\\s\\S]*?\\n\\}\\n`))?.[0] || `function ${h}() { return false; }`).join('\n');
            return (rowsAfter) => {
                const conds = [];
                const chain = { update() { return chain; }, eq(k, v) { conds.push(['eq', k, v]); return chain; }, is(k, v) { conds.push(['is', k, v]); return chain; }, select() { return Promise.resolve({ data: rowsAfter, error: null }); } };
                const w = {};
                new Function('supabase', 'window', 'RESERVATION_SQL_HINT', 'PIN_SQL_HINT', `${helpers}\n${body}`)({ from: () => chain }, w, 'hint39', 'hint45');
                return { fn: w[name], conds };
            };
        };
        const move = fnOf('supabaseMovePin'), ask = fnOf('supabaseAskPin');
        // 置き直し: updated_at を渡さないと拒む / 渡すと条件に入る / 0 行なら「別の運営が動かした」
        await assert.rejects(() => move([{ id: 1 }]).fn(1, { bossNumber: 2 }), /expectUpdatedAt/, 'updated_at 無しで動かせてしまう');
        const m = move([{ id: 1 }]);
        await m.fn(1, { bossNumber: 2, expectUpdatedAt: '2026-09-14T00:00:00+00:00' });
        assert.ok(m.conds.some(c => c[0] === 'eq' && c[1] === 'updated_at' && c[2] === '2026-09-14T00:00:00+00:00'), '置き直しが updated_at を条件にしていない');
        assert.ok(m.conds.some(c => c[1] === 'status' && c[2] === 'pinned'));
        await assert.rejects(() => move([]).fn(1, { bossNumber: 2, expectUpdatedAt: 'x' }), /別の運営が動かしました/);
        // お願い: updated_at + asked_at IS NULL。二人が同時に押しても片方だけ通る
        await assert.rejects(() => ask([{ id: 1 }]).fn(1, { deadlineAt: 'd' }), /expectUpdatedAt/);
        const a = ask([{ id: 1 }]);
        await a.fn(1, { deadlineAt: 'd', expectUpdatedAt: 'u1' });
        assert.ok(a.conds.some(c => c[0] === 'eq' && c[1] === 'updated_at' && c[2] === 'u1'), 'お願いが updated_at を条件にしていない');
        assert.ok(a.conds.some(c => c[0] === 'is' && c[1] === 'asked_at' && c[2] === null), 'お願いが asked_at IS NULL を条件にしていない (二人が同時にお願いできる)');
        await assert.rejects(() => ask([]).fn(1, { deadlineAt: 'd', expectUpdatedAt: 'u1' }), /すでにお願い済み/);
        // 読み出しが鍵 (updated_at) を持って帰る / 呼び出し側が押した時点の行の updated_at を渡す
        for (const name of ['supabaseLoadReservations', 'supabaseLoadMyReservations']) {
            const body = _client.match(new RegExp(`window\\.${name} = async function[\\s\\S]*?\\n\\};\\n`))?.[0] || '';
            assert.ok(/release_reason, updated_at'/.test(body), `${name} が updated_at を読んでいない (楽観ロックの鍵が無い)`);
        }
        const src = _fs.readFileSync(_path.join(_ROOT, 'index.html'), 'utf8').replace(/\r\n/g, '\n');
        assert.ok(/supabaseMovePin\(existing\.id, \{[\s\S]{0,200}?expectUpdatedAt: existing\.updated_at/.test(src), '置き直しが押した時点の行の updated_at を渡していない');
        assert.ok(/supabaseAskPin\(row\.id, \{[^}]*expectUpdatedAt: row\.updated_at/.test(src), 'お願いが行の updated_at を渡していない');
    });
    await testAsync('★ #10 名乗り直しの後着ガード (実行): A→B→A と戻しても、最初の A 向けの遅い応答が新しい結果を上書きしない', async () => {
        const src = _fs.readFileSync(_path.join(_ROOT, 'index.html'), 'utf8').replace(/\r\n/g, '\n');
        // 世代は setCurrentIdentity の頭で進める (下で呼ぶ _syncOpsRole が新しい世代を控えるように)
        const setId = src.match(/function setCurrentIdentity\(player\) \{[\s\S]*?\n        \}\n/)?.[0] || '';
        assert.ok(/function setCurrentIdentity\(player\) \{\s*\n\s*_identityGen\+\+;/.test(setId), 'setCurrentIdentity の頭で世代を進めていない');
        assert.ok(/let _identityGen = 0;/.test(src));
        // ---- _syncOpsRole: A の役割取得が遅い間に B → A と戻す。古い応答 (member) が新しい応答 (ops) を上書きしない
        {
            const body = src.match(/async function _syncOpsRole\(\) \{[\s\S]*?\n        \}\n/)?.[0];
            assert.ok(body, '_syncOpsRole が見つからない');
            const st = { id: 7, gen: 0, opsRole: { playerId: null, role: undefined } };
            let nth = 0, resolveFirst = null;
            const w = {
                opsRoleDomain: globalThis.opsRoleDomain,
                supabaseLoadOpsRole: () => (++nth === 1 ? new Promise(res => { resolveFirst = res; }) : Promise.resolve('ops')),
            };
            const run = new Function('st', 'window', 'console', `
                const getCurrentIdentity = () => ({ id: st.id, name: 'x' });
                const _applyOpsModeForIdentity = () => {};
                const renderSettingsTab = async () => {};
                Object.defineProperty(globalThis, '_identityGen', { get: () => st.gen, configurable: true });
                let _opsRole = st.opsRole;
                ${body}
                return { run: _syncOpsRole, get: () => _opsRole };`)(st, w, { warn() {} });
            const pA = run.run();                 // A (gen 0) — 応答が遅い
            await new Promise(r => setTimeout(r, 0));
            st.gen = 1; st.id = 8;                // B へ名乗り直し
            st.gen = 2; st.id = 7;                // A へ戻す
            await run.run();                      // A (gen 2) — 新しい応答: ops
            assert.equal(run.get().role, 'ops');
            resolveFirst(null);                   // 最初の A 向けの遅い応答: member (null)
            await pA;
            assert.equal(run.get().role, 'ops', 'A→B→A で古い役割 (member) が新しい役割 (ops) を上書きした');
            delete globalThis._identityGen;
        }
        // ---- renderMyReservations: 同じ形。古い一覧で _myResvRows を上書きしない
        {
            const body = src.match(/async function renderMyReservations\(identity\) \{[\s\S]*?\n        \}\n/)?.[0];
            assert.ok(body, 'renderMyReservations が見つからない');
            const st = { id: 7, gen: 0, writes: [] };
            let nth = 0, resolveFirst = null;
            const el = () => ({ style: {}, innerHTML: '', textContent: '' });
            const w = {
                reservationsDomain: globalThis.reservationsDomain,
                supabaseLoadMyReservations: () => (++nth === 1 ? new Promise(res => { resolveFirst = res; }) : Promise.resolve(null)),
            };
            const run = new Function('st', 'window', 'document', `
                const getCurrentIdentity = () => ({ id: st.id, name: 'x' });
                const ensureActiveSeasonLoaded = async () => ({ season: { id: 1 }, bosses: [] });
                Object.defineProperty(globalThis, '_identityGen', { get: () => st.gen, configurable: true });
                Object.defineProperty(globalThis, '_myResvRows', { set: (v) => st.writes.push(v), get: () => null, configurable: true });
                ${body}
                return renderMyReservations;`)(st, w, { getElementById: el });
            const pA = run({ id: 7 });            // A (gen 0) — 一覧の取得が遅い
            await new Promise(r => setTimeout(r, 0));
            st.gen = 1; st.id = 8; st.gen = 2; st.id = 7;   // B → A
            await run({ id: 7 });                 // A (gen 2) — 新しい応答 (null = 39 未適用扱い) が 1 回書く
            assert.equal(st.writes.length, 1);
            resolveFirst(null);                   // 最初の A 向けの遅い応答
            await pA;
            assert.equal(st.writes.length, 1, 'A→B→A で古い一覧が新しい一覧を上書きした (id が同じなので通ってしまう)');
            delete globalThis._identityGen; delete globalThis._myResvRows;
        }
    });
    await testAsync('★ #7 期限切れの 📣 お願い (返事の無い 📌) を目立たせ、まとめて外せる — 自動では外さない (実行)', async () => {
        // 期限は絶対時刻で置く (実行時の Date.now() に対して 過去 = 期限切れ / 2099 = 期限内)
        const PAST = '2026-09-13T10:15:00Z', FUTURE = '2099-01-01T00:00:00Z';
        const P = (id, o = {}) => ({ id, player_id: 7, status: 'pinned', boss_number: 1, loadout_slot: 1, asked_at: '2026-09-13T10:00:00Z', ask_deadline_at: PAST, ...o });
        const now = new Date('2026-09-14T10:20:00Z').getTime();
        // 判定: お願い済み + 期限が過ぎた だけ。下書き (未お願い) / 期限内 / 期限なし / 約束になったもの は違う
        assert.equal(rv.isExpiredPin(P(1), now), true);
        assert.equal(rv.isExpiredPin(P(2, { asked_at: null }), now), false, 'お願いしていない下書きを期限切れにしている');
        assert.equal(rv.isExpiredPin(P(3, { ask_deadline_at: FUTURE }), now), false, '期限内なのに期限切れ');
        assert.equal(rv.isExpiredPin(P(4, { ask_deadline_at: null }), now), false, '期限なしを期限切れにしている');
        assert.equal(rv.isExpiredPin(P(5, { status: 'approved' }), now), false, '引き受けた約束を期限切れにしている');
        assert.equal(rv.isExpiredPin(null, now), false);
        assert.deepEqual(rv.expiredPins([P(1), P(3, { ask_deadline_at: FUTURE }), P(6)], now).map(r => r.id), [1, 6]);
        assert.deepEqual(rv.expiredPins(null, now), []);
        assert.ok(rv.RELEASE_JP.ask_expired, '期限切れで外した理由の日本語が無い (終わったものの欄に英語が出る)');
        // 集計 (畳んだカードの 1 行・コックピットと同じ材料): 期限切れがあれば注意色
        const lay = globalThis.opsLayoutDomain;
        const sum = (reservations) => lay.summarize({ season: { id: 1, current_level: 1 }, bosses: [], players: [], reservations }).summaries.opsSecReserve;
        assert.match(sum({ pending: 0, approved: 1, expired: 2 }).text, /⏰ 期限切れ 2/);
        assert.equal(sum({ pending: 0, approved: 1, expired: 2 }).bad, true);
        assert.doesNotMatch(sum({ pending: 0, approved: 1, expired: 0 }).text, /期限切れ/);
        assert.equal(sum({ pending: 0, approved: 1 }).bad, false, '期限切れ無し・承認待ち無しなら注意色にしない');
        // 配線: 一覧の件数と行の印、段階とコックピットの材料に expired が入る、まとめて外す
        const src = _fs.readFileSync(_path.join(_ROOT, 'index.html'), 'utf8').replace(/\r\n/g, '\n');
        assert.ok(/const expiredPins = rv\.expiredPins \? rv\.expiredPins\(pins\) : \[\];/.test(src) && /⏰ 期限切れ \$\{expiredPins\.length\}/.test(src), '一覧の件数に期限切れが無い');
        assert.ok(/rv\.isExpiredPin\(r\) \? '⏰ 期限切れ' : '📣 お願い中'/.test(src), '行に「⏰ 期限切れ」の印が無い');
        assert.equal((src.match(/expired: \(window\.reservationsDomain\?\.expiredPins\?\.\(_resv\.rows\) \|\| \[\]\)\.length/g) || []).length, 2, '段階とコックピットの予約件数に expired を渡していない (2 か所)');
        assert.ok(/if \(!o\.quiet\) showNotification\(o\.done \|\| '更新しました'\);/.test(src), '_resvTransition が quiet を見ない (まとめて外すと 1 件ごとに通知が出る)');
        // 実行: 期限切れだけを 1 件ずつ RPC (期待状態 pinned・理由 ask_expired) で外す。確認で止められる
        const body = src.match(/async function _opsReleaseExpiredPins\(\) \{[\s\S]*?\n        \}\n/)?.[0];
        assert.ok(body, '_opsReleaseExpiredPins が無い');
        const mk = (rows, yes) => {
            const calls = { tr: [], notif: [], recompute: 0 };
            const api = {
                _resv: { rows }, confirm: () => yes,
                showNotification: (m) => calls.notif.push(m),
                _resvTransition: async (id, to, o) => { calls.tr.push({ id, to, ...o }); return true; },
                computeAndRenderOptimalPlan: async () => { calls.recompute++; },
                window: { reservationsDomain: rv },
            };
            const fn = new Function('api', `const { _resv, confirm, showNotification, _resvTransition, computeAndRenderOptimalPlan, window } = api; let _opsPlanSel = 1, _opsPlanFocus = 1;
                ${body}
                return _opsReleaseExpiredPins;`)(api);
            return { fn, calls };
        };
        const rows = [P(1), P(3, { ask_deadline_at: FUTURE }), P(6), P(9, { asked_at: null })];
        const a = mk(rows, true);
        await a.fn();
        assert.deepEqual(a.calls.tr.map(t => t.id), [1, 6], '期限切れ以外 (期限内・下書き) まで外している');
        assert.ok(a.calls.tr.every(t => t.to === 'released' && t.expectFrom === 'pinned' && t.reason === 'ask_expired' && t.quiet === true), 'RPC の期待状態・理由・quiet が違う');
        assert.equal(a.calls.recompute, 1, '外したあと算出し直していない');
        const b = mk(rows, false);
        await b.fn();
        assert.equal(b.calls.tr.length, 0, '確認で止めたのに外している');
        const c = mk([P(3, { ask_deadline_at: FUTURE })], true);
        await c.fn();
        assert.equal(c.calls.tr.length, 0); assert.ok(c.calls.notif.some(m => /ありません/.test(m)));
    });
    test('★ #9 シミュレーター (実行): 予測は slvSimDomain.predictDamage が唯一 — 実績 0 の人で NaN% を出さない', () => {
        const src = _fs.readFileSync(_path.join(_ROOT, 'index.html'), 'utf8').replace(/\r\n/g, '\n');
        const body = src.match(/function runSimulator\(\) \{[\s\S]*?\n        \}\n/)?.[0];
        assert.ok(body, 'runSimulator が無い');
        assert.ok(!/base\.total \* \(targetRatio \/ currentRatio\)/.test(body), '画面が比例計算を書き直している (ドメインと二重)');
        const TABLE = { '400': 900, '500': 1000, '600': 1200 };
        const mk = (data, selected, target, table = TABLE, domain = globalThis.slvSimDomain) => {
            const els = {};
            const el = (id) => (els[id] ||= { id, style: {}, textContent: '', innerHTML: '', value: '' });
            el('simPlayerSelect').value = selected; el('simTargetSlv').value = String(target);
            const api = {
                document: { getElementById: el },
                currentData: data, _slvMax: 1000, slvRatioTable: table,
                _simBaseOf: (p) => ({ total: Number(p.damage) || 0, replaced: 0, recorded: Number(p.damage) || 0 }),
                formatDamage: (v) => `${(v / 1e9).toFixed(2)}B`,
                window: { slvSimDomain: domain },
            };
            new Function('api', `const { document, currentData, _slvMax, slvRatioTable, _simBaseOf, formatDamage, window } = api;
                ${body}
                runSimulator();`)(api);
            return els;
        };
        const data = [{ player: 'ゼロ', syncLevel: 500, damage: 0, attacks: [] }, { player: '普通', syncLevel: 400, damage: 5e9, attacks: [] }];
        const text = (els) => Object.values(els).map(e => `${e.textContent}${e.innerHTML}`).join('');
        // 実績 0: 結果を出さず、理由を出す。NaN はどこにも出ない
        const z = mk(data, 'ゼロ', 600);
        assert.equal(z.simError.style.display, 'block'); assert.match(z.simError.textContent, /実績ダメージが無い/);
        assert.equal(z.simResult.style.display, 'none'); assert.equal(z.simTableWrapper.style.display, 'none');
        assert.ok(!/NaN/.test(text(z)), 'NaN が画面に出ている');
        // 普通の人: 予測はドメインの値そのもの (5B × 1200/900)
        const n = mk(data, '普通', 600);
        assert.equal(n.simError.style.display, 'none'); assert.equal(n.simResult.style.display, 'block');
        const expected = globalThis.slvSimDomain.predictDamage({ damage: 5e9, curSlv: 400, targetSlv: 600, table: TABLE });
        assert.equal(n.simPredictedDmg.textContent, `${(expected / 1e9).toFixed(2)}B`);
        assert.match(n.simDiff.textContent, /\+33\.3%/);
        assert.ok(!/NaN/.test(text(n)));
        // 原因を分けて案内する (E/F/G/H の Codex 指摘): 補正値が負や Infinity (真偽値の検査では通る) → 補正データのエラー、実績のせいにしない
        const badTable = { '400': 900, '500': 1000, '600': -1 };
        const bt = mk(data, '普通', 600, badTable);
        assert.equal(bt.simError.style.display, 'block'); assert.match(bt.simError.textContent, /補正データ/, '補正値 -1 を「実績ダメージが無い」と案内している');
        assert.doesNotMatch(bt.simError.textContent, /実績ダメージ/);
        const infTable = { '400': 900, '500': 1000, '600': Infinity };
        assert.match(mk(data, '普通', 600, infTable).simError.textContent, /補正データ/, '補正値 Infinity を「実績ダメージが無い」と案内している');
        // ドメインが読めていない → 部品のエラー
        const nd = mk(data, '普通', 600, TABLE, null);
        assert.equal(nd.simError.style.display, 'block'); assert.match(nd.simError.textContent, /slvSim\.js/, 'ドメイン未読込を実績のせいにしている');
    });
