        assert.ok(/plan\.basisPlanId = basisPlanId;/.test(html), '基準の配信IDを焼き込んでいない');
        assert.ok(/if \(_opsLastPlan\?\.stickyOn && Number\(basis \|\| 0\) !== Number\(prevPlanId \|\| 0\)\) \{/.test(html),
            '配信直前に基準のずれを照合していない');
