        assert.ok(html.includes('その人が出られるブロックで組むときに置きます。</div>` : \'\'}'), '対象外の案内の結びが無い');
        assert.ok(!/handleOpsPublishPlan/.test(ro), '組み直しだけのはずが配信の確認を出している');
        const fl = html.match(/async function _recomputeAndOfferPublish\([\s\S]*?\n        \}\n/)?.[0] || '';
