    test('★ unionRanking: 1体をユニオン内で並べる。持っていない人は出さない', () => {
        const players = [{ id: 1, name: 'あ' }, { id: 2, name: 'い' }, { id: 3, name: 'う' }];
        const by = dom.byPlayerCharacter([
            { player_id: 1, character_name: 'ラピ', combat: 100, lv: 900 },
            { player_id: 2, character_name: 'ラピ', combat: 300, lv: 100 },
            { player_id: 3, character_name: 'アリス', combat: 500 },
        ]);
        const r = dom.unionRanking(by, players, 'ラピ', 'combat', 1);
        assert.deepEqual(r.list.map(x => x.playerId), [2, 1], '強い順になっていない');
        assert.equal(r.myRank, 2, '自分の順位が違う');
        assert.equal(r.field.label, '戦闘力');
        // ★ 持っていない人を 0 として最下位に並べない (「持っていない」と「育っていない」は違う)
        assert.equal(r.list.length, 2, '持っていない人まで並べている');
        // 項目を変えると並びも変わる
        assert.deepEqual(dom.unionRanking(by, players, 'ラピ', 'lv', 1).list.map(x => x.playerId), [1, 2]);
        assert.equal(dom.unionRanking(by, players, 'ラピ', 'combat', 3).myRank, null, '持っていない自分に順位が付いている');
        assert.deepEqual(dom.unionRanking(by, players, 'いないキャラ', 'combat', 1).list, []);
        // ★ 同点は名前順で固定する — 描き直すたびに順位が入れ替わると信用されない
        const tie = dom.byPlayerCharacter([
            { player_id: 1, character_name: 'ラピ', combat: 100 },
            { player_id: 2, character_name: 'ラピ', combat: 100 },
            { player_id: 3, character_name: 'ラピ', combat: 100 },
        ]);
        const t1 = dom.unionRanking(tie, [{ id: 3, name: 'う' }, { id: 1, name: 'あ' }, { id: 2, name: 'い' }], 'ラピ', 'combat', 1);
        const t2 = dom.unionRanking(tie, [{ id: 1, name: 'あ' }, { id: 2, name: 'い' }, { id: 3, name: 'う' }], 'ラピ', 'combat', 1);
        assert.deepEqual(t1.list.map(x => x.name), ['あ', 'い', 'う'], '同点の並びが名前順でない');
        assert.deepEqual(t1.list.map(x => x.playerId), t2.list.map(x => x.playerId), '渡す順で並びが変わる');
        // ★ 同名のメンバーがいると、名前だけの並べ替えでは渡す順に左右される (Codex指摘)
        const same = [{ id: 2, name: 'あ' }, { id: 1, name: 'あ' }];
        const r1 = dom.unionRanking(tie, same, 'ラピ', 'combat', 1);
        const r2 = dom.unionRanking(tie, same.slice().reverse(), 'ラピ', 'combat', 1);
        assert.deepEqual(r1.list.map(x => x.playerId), r2.list.map(x => x.playerId), '同名だと渡す順で並びが変わる');
        assert.equal(r1.myRank, r2.myRank, '同名だと自分の順位が渡す順で変わる');
    });

    test('★ dpsOf / dpsScore: 火力役だけの「有利コード＋攻撃」を出す', () => {
        // ★ ユニオンレイドの火力は火力役の 有利コード と 攻撃 の OP で決まる。
        //   バフ役まで混ぜて合計すると、実際の火力差と関係のない数字になる (2026-09-10 ユーザー指摘)。
        //   既定がバースト3 なのは第44回の実データの裏づけ (全凸300枠のうち B3 が144枠)
        const burst = (n) => ({ 火力A: 'B3', 火力B: 'B3', バフ: 'B2', 前衛: 'B1' })[n];
        const team = ['火力A', 'バフ', '前衛', '火力B'];
        assert.deepEqual(dom.dpsOf(team, burst, null), ['火力A', '火力B'], '既定がバースト3でない');
        assert.deepEqual(dom.dpsOf(team, burst, { on: ['バフ'] }), ['火力A', 'バフ', '火力B'], '手で足せない');
        assert.deepEqual(dom.dpsOf(team, burst, { off: ['火力A'] }), ['火力B'], '手で外せない');
        assert.deepEqual(dom.dpsOf(team, burst, { on: ['前衛'], off: ['火力A', '火力B'] }), ['前衛'],
            '足し引きを同時に指定できない');
        // ★ 壊れた保存データで同じ名前が両方に入ることがある。**on を優先**すると決めておく
        assert.deepEqual(dom.dpsOf(['バフ'], burst, { on: ['バフ'], off: ['バフ'] }), ['バフ'],
            'on と off が食い違ったときの向きが決まっていない');
        assert.deepEqual(dom.dpsOf(['火力A'], burst, { on: ['火力A'], off: ['火力A'] }), ['火力A']);
        assert.deepEqual(dom.dpsOf(null, burst, null), []);
        assert.equal(dom.isDps('火力A', burst, null), true);
        assert.equal(dom.isDps('バフ', burst, null), false);

        const ol = (a, b) => ({ overload: { 有利コード: a, 攻撃力: b } });
        const mine = { 火力A: ol(60, 30), 火力B: ol(50, 20), ひとりだけ: ol(99, 99) };
        const theirs = { 火力A: ol(65, 35), 火力B: ol(40, 25) };
        const s1 = dom.dpsScore(['火力A', '火力B'], mine, theirs);
        assert.equal(s1.n, 2);
        assert.equal(s1.mine, 160); assert.equal(s1.theirs, 165); assert.equal(s1.diff, 5);
        // ★ 片方しか持っていない体は合計に混ぜない — 違う顔ぶれの合計を「差」と呼ぶことになる
        const s2 = dom.dpsScore(['火力A', 'ひとりだけ'], mine, theirs);
        assert.equal(s2.n, 1, '片方欠けを数に入れている');
        assert.equal(s2.missing, 1, '外した体を数えていない');
        assert.equal(s2.mine, 90, '片方欠けの体を自分の合計に足している');
        assert.equal(s2.theirs, 100, '片方欠けの体を相手の合計に足している');
        assert.deepEqual(dom.dpsScore([], mine, theirs), { n: 0, missing: 0, mine: 0, theirs: 0, diff: 0 });
    });

    test('★ unionDpsRanking: 火力役の合計でユニオン内の順位を出す', () => {
        // ★ その体を**すべて持っている人だけ**を並べる — 1体でも欠けている人を混ぜると、
        //   違う顔ぶれの合計を並べて「順位」と呼ぶことになる
        const ol = (a, b) => ({ overload: { 有利コード: a, 攻撃力: b } });
        const by = dom.byPlayerCharacter([
            { player_id: 1, character_name: 'A', ...ol(50, 20) }, { player_id: 1, character_name: 'B', ...ol(40, 10) },
            { player_id: 2, character_name: 'A', ...ol(60, 30) }, { player_id: 2, character_name: 'B', ...ol(50, 20) },
            { player_id: 3, character_name: 'A', ...ol(99, 99) },   // B を持っていない
        ]);
        const players = [{ id: 1, name: 'あ' }, { id: 2, name: 'い' }, { id: 3, name: 'う' }];
        const r = dom.unionDpsRanking(by, players, ['A', 'B'], 1);
        assert.deepEqual(r.list.map(x => x.playerId), [2, 1], '合計の大きい順になっていない');
        assert.equal(r.list[0].value, 160); assert.equal(r.list[1].value, 120);
        assert.equal(r.myRank, 2, '自分の順位が違う');
        assert.equal(r.list.length, 2, '1体でも欠けている人を並べている');
        // 火力役が0体なら順位も出さない (誰でも「全部持っている」ことになってしまう)
        assert.deepEqual(dom.unionDpsRanking(by, players, [], 1), { list: [], myRank: null, myMissing: null });
        // ★ 「持っていない」と「持っているが装備の記録が無い」を分ける — 直し方が違う
        const mix = dom.byPlayerCharacter([
            { player_id: 1, character_name: 'A', ...ol(50, 20) },
            { player_id: 1, character_name: 'B', overload: null },   // 持っているが記録が無い
            { player_id: 2, character_name: 'A', ...ol(60, 30) }, { player_id: 2, character_name: 'B', ...ol(50, 20) },
        ]);
        const r2 = dom.unionDpsRanking(mix, players, ['A', 'B'], 1);
        assert.equal(r2.myRank, null);
        assert.deepEqual(r2.myMissing, { character: 'B', reason: 'no_value' }, '記録が無いのを未所持にしている');
        assert.deepEqual(r2.list.map(x => x.playerId), [2], '記録の無い人を並べている');
        const r3 = dom.unionDpsRanking(by, players, ['A', 'B'], 3);   // 3 は B を持っていない
        assert.deepEqual(r3.myMissing, { character: 'B', reason: 'no_char' }, '未所持を記録なしにしている');
        assert.equal(dom.unionDpsRanking(by, players, ['A', 'B'], 1).myMissing, null, '揃っている人に理由が付いている');
        assert.equal(dom.unionDpsRanking(by, players, ['A'], 9).myRank, null);
        // ★ 同点は名前 → id で固定する (描き直すたびに順位が入れ替わると信用されない)
        const tie = dom.byPlayerCharacter([
            { player_id: 1, character_name: 'A', ...ol(50, 20) },
            { player_id: 2, character_name: 'A', ...ol(50, 20) },
            { player_id: 3, character_name: 'A', ...ol(50, 20) },
        ]);
        const t1 = dom.unionDpsRanking(tie, [{ id: 3, name: 'う' }, { id: 1, name: 'あ' }, { id: 2, name: 'い' }], ['A'], 1);
        const t2 = dom.unionDpsRanking(tie, [{ id: 1, name: 'あ' }, { id: 2, name: 'い' }, { id: 3, name: 'う' }], ['A'], 1);
        assert.deepEqual(t1.list.map(x => x.name), ['あ', 'い', 'う'], '同点の並びが名前順でない');
        assert.deepEqual(t1.list.map(x => x.playerId), t2.list.map(x => x.playerId), '渡す順で並びが変わる');
        const same = [{ id: 2, name: 'あ' }, { id: 1, name: 'あ' }];
        assert.deepEqual(dom.unionDpsRanking(tie, same, ['A'], 1).list.map(x => x.playerId),
            dom.unionDpsRanking(tie, same.slice().reverse(), ['A'], 1).list.map(x => x.playerId),
            '同名だと渡す順で並びが変わる');
    });

    test('★ quickCells: 出す値は持ち主・色は自分と相手のどちらが上か', () => {
        const r = (o) => ({ grade: 3, core: 0, skill1_lv: 10, skill2_lv: 9, ulti_skill_lv: 10, overload: o });
        const mine = r({ 攻撃力: 10, 有利コード: 50 });
        const theirs = r({ 攻撃力: 30, 有利コード: 50 });
        const cells = dom.quickCells(mine, mine, theirs);
        assert.deepEqual(cells.map(c => c.short), ['凸', 'ｽｷﾙ', '攻', '有'], '項目か順番が違う');
        assert.equal(cells[1].text, '10/9/10', 'S1/S2/バーストを1行にしていない');
        assert.equal(cells[2].text, '10.00%', '持ち主の値を出していない');
        assert.equal(cells[2].lead, 'theirs', '相手が上なのに色が付かない');
        assert.equal(cells[3].lead, 'same', '同じなのに差が付いている');
        // 相手の編成を見るときは相手の値を出す (色はそのまま「どちらが上か」)
        const own = dom.quickCells(theirs, mine, theirs);
        assert.equal(own[2].text, '30.00%');
        assert.equal(own[2].lead, 'theirs');
        // 記録が無い人を 0 として比べない
        const none = dom.quickCells(mine, mine, null);
        assert.equal(none[2].lead, 'unknown', '相手が居ないのに比べている');
        assert.equal(dom.quickCells(null, mine, theirs)[2].text, '—');
        // ★ スキルが1つでも欠けたら比べない — 欠けを Lv0 として足すと、取り込めていない
        //   だけの人に「育っていない」という色が付く (Codex指摘 2026-09-10)
        const half = { grade: 3, core: 0, skill1_lv: 10, skill2_lv: null, ulti_skill_lv: null, overload: {} };
        const full = { grade: 3, core: 0, skill1_lv: 7, skill2_lv: 7, ulti_skill_lv: 7, overload: {} };
        assert.equal(dom.quickCells(half, half, full)[1].lead, 'unknown',
            'スキルの欠けを Lv0 として比べている');
        assert.equal(dom.quickCells(half, half, full)[1].text, '10/—/—', '欠けを 0 と書いている');
        assert.equal(dom.quickCells(full, full, half)[1].lead, 'unknown', '相手側が欠けても同じ');
        // ★ 全部そろっていれば、ちゃんと色が付く (欠けの判定を入れた副作用で色が消えていないか)
        const hi = { grade: 3, core: 0, skill1_lv: 10, skill2_lv: 10, ulti_skill_lv: 10, overload: {} };
        assert.equal(dom.quickCells(full, full, hi)[1].lead, 'theirs', '全部そろっているのに色が付かない');
        assert.equal(dom.quickCells(hi, hi, full)[1].lead, 'mine', '自分が上のときに色が付かない');
        assert.equal(dom.quickCells(full, full, full)[1].lead, 'same', '同じなのに差が付いている');
        // ★ S1 が同じでも S2・バーストで差が付く — 3つとも見ていないと拾えない
        const s1same = { grade: 3, core: 0, skill1_lv: 10, skill2_lv: 7, ulti_skill_lv: 7, overload: {} };
        assert.equal(dom.quickCells(s1same, s1same, hi)[1].lead, 'theirs',
            'スキル1しか見ていない (S2・バーストの差を拾えない)');
        assert.equal(dom.quickCells(hi, hi, s1same)[1].lead, 'mine', '同上 (自分が上の側)');
    });
    test('★ teamGaps: 編成の並びのまま差を出す (並べ替えは rankSquad の仕事)', () => {
        // 差はオーバーロード合計 (有利コード＋攻撃) で見る — 戦闘力はシンクロレベル順にしかならない
        const ol = (a, b) => ({ overload: { 有利コード: a, 攻撃力: b } });
        const mine = { 'ラピ': ol(5, 5), 'アリス': ol(20, 20) };
        const theirs = { 'ラピ': ol(9, 11), 'ドロシー': ol(30, 30) };
        const g = dom.teamGaps(['ラピ', 'アリス', 'ドロシー'], mine, theirs);
        assert.deepEqual(g.map(x => x.character), ['ラピ', 'アリス', 'ドロシー'], '編成の並びを崩している');
        assert.equal(g[0].gap, 10);
        assert.equal(g[1].gap, null, '片方しか無いのに差を出している');
        assert.equal(g[1].hasBoth, false);
        assert.equal(g[2].gap, null);
        assert.deepEqual(dom.teamGaps(null, mine, theirs), []);
    });

    test('★ importTargets (2026-09-15): 全員 / 未取り込みの人だけ / 選んだ人 — ひも付けの無い人はどれにも入らない', () => {
        const mk = (id, name, openid) => ({ id, name, blabla_openid: openid });
        const ps = [mk(1, 'あ', '11'), mk(2, 'い', '22'), mk(3, 'う', null), mk(4, 'え', '44')];
        const rows = [{ player_id: 1, status: 'ok' }, { player_id: 2, status: 'private' }, { player_id: 3, status: 'no_openid' }];
        const ids = (r) => r.targets.map(p => p.id);
        assert.deepEqual(ids(dom.importTargets(ps, rows, { scope: 'all' })), [1, 2, 4]);
        assert.deepEqual(ids(dom.importTargets(ps, rows, { scope: 'missing' })), [2, 4], '取り込み済み (ok) を外していない / 状態の無い人を未取り込みに数えていない');
        assert.deepEqual(ids(dom.importTargets(ps, rows, { scope: 'picked', pickedIds: ['4', 3, 99] })), [4], '選んだ人 (文字列の id) / ひも付けの無い人 / いない人');
        assert.deepEqual(dom.importTargets(ps, rows, { scope: 'all' }).counts, { all: 3, missing: 2, picked: 0, missingPrivate: 1 }, '非公開の内訳が無い');
        assert.equal(dom.importTargets(ps, [{ player_id: 1, status: 'ok' }], {}).counts.missingPrivate, 0);
        // 43 未適用 (null) は誰も ok でない = 全員が未取り込み。知らない scope / 省略 は全員
        assert.deepEqual(ids(dom.importTargets(ps, null, { scope: 'missing' })), [1, 2, 4]);
        assert.equal(dom.importTargets(ps, rows, { scope: 'なにか' }).scope, 'all');
        assert.deepEqual(ids(dom.importTargets(ps, rows)), [1, 2, 4]);
        assert.deepEqual(dom.IMPORT_SCOPES, ['all', 'missing', 'picked']);
        assert.equal(dom.IMPORT_SCOPE_JP.missing, '未取り込みの人だけ');
    });

    test('★ privateTargets: 声をかけるのは非公開の人だけ (未ひも付けには送らない)', () => {
        // 未ひも付けは**運営の作業待ち**。本人に言っても何もできないので送ってはいけない
        const L = (id, name) => ({ id, name, blabla_openid: `${id}00` });
        const players = [L(1, 'あ'), L(2, 'い'), L(3, 'う'), L(4, 'え')];
        const rows = [
            { player_id: 1, status: 'private' }, { player_id: 2, status: 'no_openid' },
            { player_id: 3, status: 'ok' }, { player_id: 4, status: 'error' },
        ];
        assert.deepEqual(dom.privateTargets(rows, players).map(p => p.id), [1]);
        // ★ 状態は private のまま識別子だけ外れていることがある (付け替えの途中など)。
        //   公開してもらっても運営が付け直すまで取れないので、本人には何もできない
        // ★ 空文字も「外れている」— null だけ見ると、空で保存された行をひも付け済みと誤認する
        const unlinked = [L(1, 'あ'), { id: 5, name: 'お', blabla_openid: null },
            { id: 6, name: 'か', blabla_openid: '' }, { id: 7, name: 'き' }];
        const r5 = [{ player_id: 1, status: 'private' }, { player_id: 5, status: 'private' },
            { player_id: 6, status: 'private' }, { player_id: 7, status: 'private' }];
        assert.deepEqual(dom.privateTargets(r5, unlinked).map(p => p.id), [1],
            'ひも付けの外れている人に「公開して」と言っている (公開しても取れない)');
        assert.deepEqual(dom.privateTargets(null, players), []);
        assert.deepEqual(dom.privateTargets(rows, null), []);
        // 文面は「何をすればよいか」を言う
        assert.match(dom.PUBLISH_ASK.body, /ゲームカードを公開/);
        assert.ok(dom.PUBLISH_ASK.title && dom.PUBLISH_ASK.url, 'お願いの題と行き先が無い');
    });

