    await testAsync('★ 実行: ブロックの保存 — 入口で検査 / RPC が本線 / 50 未適用だけ読んで混ぜて書く / RPC の別エラーは投げる (Codex指摘 2026-10-18)', async () => {
        const client = _grRd('js/supabase-client.js').split(String.fromCharCode(13)).join('');
        const body = client.match(/window\.supabaseUpdateSeasonBlocks = async function[\s\S]*?\n\};\n/)?.[0] || '';
        assert.ok(body, '保存の関数が無い');
        const mk = (rpcAnswer, meta = { damages_snapshot: [1], blocks: [{ name: 'x', from: 5, to: 4 }] }) => {
            const calls = { rpc: [], select: 0, update: [] };
            const supabase = {
                rpc: async (name, args) => { calls.rpc.push({ name, args }); return rpcAnswer(args); },
                from: () => ({
                    select: () => { calls.select++; return { eq: () => ({ eq: () => ({ maybeSingle: async () => ({ data: { metadata: meta }, error: null }) }) }) }; },
                    update: (patch) => { calls.update.push(patch); return { eq: () => ({ eq: () => ({ select: async () => ({ data: [{ id: 1 }], error: null }) }) }) }; },
                }),
            };
            const w = {};
            new Function('supabase', 'window', body)(supabase, w);
            return { fn: w.supabaseUpdateSeasonBlocks, calls };
        };
        const two = [{ name: '前半', from: 5, to: 14 }, { name: '後半', from: 15, to: 4 }];
        // 入口で検査: 壊れた区切りはどこにも書かない
        const bad = mk(async () => ({ error: null }));
        await assert.rejects(() => bad.fn(36, [{ name: '朝', from: 6, to: 8 }, { name: '夜', from: 9, to: 4 }]), /ブロックの区切りが正しくありません/);
        assert.equal(bad.calls.rpc.length + bad.calls.select + bad.calls.update.length, 0, '壊れた区切りで DB に触っている');
        // RPC が通れば表は触らない。既定と同じ内容は null (鍵を消す)
        const ok = mk(async () => ({ error: null }));
        assert.deepEqual(await ok.fn(36, two), two);
        assert.deepEqual(ok.calls.rpc, [{ name: 'ops_set_season_blocks', args: { p_season_id: 36, p_blocks: two } }]);
        assert.equal(ok.calls.select + ok.calls.update.length, 0, 'RPC が通ったのに表を触っている');
        assert.equal(await ok.fn(36, globalThis.raidBlocksDomain.DEFAULT_BLOCKS), null);
        assert.equal(ok.calls.rpc[1].args.p_blocks, null, '既定と同じ内容を鍵として書いている');
        // 50 未適用 (PGRST202) → 読んで混ぜて書く。他の鍵 (damages_snapshot) は残す
        const fb = mk(async () => ({ error: { code: 'PGRST202', message: 'Could not find the function public.ops_set_season_blocks' } }));
        assert.deepEqual(await fb.fn(36, two), two);
        assert.equal(fb.calls.select, 1); assert.equal(fb.calls.update.length, 1);
        assert.deepEqual(fb.calls.update[0], { metadata: { damages_snapshot: [1], blocks: two } }, 'フォールバックで他の鍵を消している / blocks を書いていない');
        await fb.fn(36, null);
        assert.deepEqual(fb.calls.update[1], { metadata: { damages_snapshot: [1] } }, 'null で鍵を消していない');
        // RPC の別のエラー (終了済みシーズン等) はそのまま投げ、フォールバックしない。文言が似ていてもコードが違えば同じ
        const other = mk(async () => ({ error: { code: 'P0001', message: '対象シーズンは既にアクティブではありません' } }));
        await assert.rejects(() => other.fn(36, two), (e) => /アクティブではありません/.test(e?.message));
        assert.equal(other.calls.select + other.calls.update.length, 0, 'RPC が断ったのに読んで書いている');
        const lookalike = mk(async () => ({ error: { code: '42883', message: 'Could not find the function public.ops_set_season_blocks' } }));
        await assert.rejects(() => lookalike.fn(36, two));
        assert.equal(lookalike.calls.select + lookalike.calls.update.length, 0, '文言の一致でフォールバックしている');
        // 既定に戻せるのは null だけ。[] / オブジェクト / 文字列 は断る (黙って鍵を消さない)
        const strict = mk(async () => ({ error: null }));
        for (const bad of [[], {}, 'x', 0]) {
            await assert.rejects(() => strict.fn(36, bad), /配列で渡してください/, `${JSON.stringify(bad)} を通している`);
        }
        assert.equal(strict.calls.rpc.length, 0, '壊れた入力で RPC を呼んでいる');
        assert.equal(await strict.fn(36, undefined), null); assert.equal(await strict.fn(36, null), null);
        assert.ok(strict.calls.rpc.every(c => c.args.p_blocks === null));
    });

    test('★ 配線: 🧱 ブロックのぶんだけ配信 — 焼き込み / ボタンの文言 / ホームはその範囲だけ + 案内 / 差分もその範囲 (2026-10-18)', () => {
        const html = _grRd('index.html').split(String.fromCharCode(13)).join('');
        // 算出時に印を焼き込む (ブロックで組んだときだけ)
        assert.ok(/if \(blk\) plan\.blockScope = \{ idx: blk\.idx, letter: blk\.letter, name: blk\.name, short: blk\.short, range: blk\.range, label: blk\.label, from: blk\.from, to: blk\.to, slots: blk\.slots\.slice\(\) \};/.test(html), 'blockScope を焼き込んでいない (5 つの欄も)');
        // 配信ボタンに何を配信するかを書く
        assert.ok(/pubBtn\.textContent = plan\.blockScope && window\.raidBlocksDomain\s*\n\s*\? `📤 \$\{plan\.blockScope\.short \|\| plan\.blockScope\.name\} のぶんを配信 \(\$\{window\.raidBlocksDomain\.attackCountIn\(plan, plan\.blockScope\)\}凸\)` : '📤 このプランを配信';/.test(html), '配信ボタンの文言が無い');
        // ホーム: 配信を読んだ直後にその範囲だけに絞る (以後の 3 つの表示・ヒーローはみな絞ったプランを見る)
        const home = html.match(/async function renderMyPublishedPlan\(identity\) \{[\s\S]*?\n        \}\n/)?.[0] || '';
        assert.ok(/const pubScope = pubSel \? pubSel\.block : \(pub\.plan\?\.blockScope \|\| null\);\s*\n\s*const plan0 = \(pubScope && window\.raidBlocksDomain\) \? window\.raidBlocksDomain\.scopePlan\(pub\.plan, pubScope\) : pub\.plan;/.test(home), 'ホームで範囲に絞っていない (選んだブロック)');
        // ✅ 決定の印は最新の行が決定のときだけ (S4 引き継ぎ 5): 後に従来の配信があれば、範囲に絞った決定を時間割にしない
        assert.ok(/const plan = \(!decRow && plan0 && plan0\.decided\) \? \(\(\{ decided: _dec, \.\.\.rest \}\) => rest\)\(plan0\) : plan0;/.test(home), '後に従来の配信があるのに決定の印を残している');
        assert.ok(/🧱 <b>\$\{escapeHtml\(plan\.blockScope\.label\)\}<\/b> のぶんの配信です。\$\{laterPublished \? '上のチップでほかのブロックの配信も見られます。' : '次のブロックの割当はまだ決まっていません/.test(html), 'どのブロックの配信かの案内が無い');
        assert.ok(/\$\{scopeLine\}\$\{condLine\}/.test(html), '案内を出していない');
        assert.ok(/このブロック \(\$\{escapeHtml\(plan\.blockScope\.label\)\}\) にあなたの凸はありません。次のブロックの配信を待ってください。/.test(html), '割当なしの文言がブロックを知らない');
        // 配信: 差分 (L5 の提示・L4 の通知) は範囲で見る / 確認の文言
        const pub = html.match(/async function handleOpsPublishPlan\(\) \{[\s\S]*?\n        \}\n/)?.[0] || '';
        assert.ok(/publishDiff = window\.planDiffDomain\.diffPlans\(sc\(prevPlan\), sc\(_opsLastPlan\)\);/.test(pub), '差分を範囲で見ていない');
        assert.ok(/const sc = \(p\) => \(scopeNow && window\.raidBlocksDomain && p\) \? window\.raidBlocksDomain\.scopePlan\(p, scopeNow\) : p;/.test(pub), '絞る関数が無い');
        assert.ok(/のぶん \(\$\{window\.raidBlocksDomain\.attackCountIn\(_opsLastPlan, _opsLastPlan\.blockScope\)\}凸\) を配信します。/.test(pub), '確認の文言が無い');
        assert.ok(/const msg = scopeMsg \+ '📤 現在表示中のプランを全メンバーに配信しますか？'/.test(pub), '確認の文言に足していない');
        // Codex指摘 (2104924): ① 起点はブロックの頭より前にしない ② 配信の版を上げる ③ 予約も範囲で ④ 自分の割当の変化 (L3) も前回を範囲で ⑤ 共有画像も範囲で
        assert.ok(/function _opsPlanStartSlot\(options, base\) \{[\s\S]*?return window\.raidBlocksDomain\.laterSlot\(base, bs\) \|\| base;/.test(html) && /currentSlot: _opsPlanStartSlot\(options, /.test(html), '起点をブロックの頭と比べていない');
        assert.ok(/blockStartSlot: blk \? _hourKey\(blk\.from\) : null \};/.test(html), 'ブロックの頭を渡していない');
        assert.ok(/from: blk \? \(plan\.currentSlot === _hourKey\(blk\.from\) \? 'block' : 'now'\) : \(plan\.currentSlot === 'h05' \? 'day' : _opsPlanStartMode\),/.test(html), '起点の焼き込みがブロックを知らない (頭から / 途中から)');
        assert.ok(/const PLAN_SCHEMA = 4;/.test(html), '配信の版を 4 (決定) に上げていない (古い版が決定の行を 1 日ぶんとして見てしまう)');
        assert.ok(/window\._planSchemaOf\(plan\)/.test(_grRd('js', 'practice', 'guide.js')), '練習の配信が版の付け方を揃えていない');
        // 20時 → 夜 (21〜翌0時) のブロックを組む: 起点は laterSlot で h21 になり、ブロックの頭より前には置かれない (統合)
        const rbd2 = globalThis.raidBlocksDomain, night = rbd2.normalize(null).blocks[4];
        const startSlot = rbd2.laterSlot('h20', 'h21');
        const ip = compute({ ...timeInput([boss(1, 'fire', { remainingB: 60 })], [
            player('夕方だけ', { fire: 30 }, { availableSlots: ['h18', 'h19', 'h20'] }),
            player('夜の人', { fire: 30 }, { availableSlots: ['h20', 'h21', 'h22'] }),
            player('いつでも', { fire: 30 }),
        ], { currentSlot: startSlot, onlyAvailableNow: true }), timeStrict: true, availableAtSlots: night.slots, availableAtLabel: night.label });
        const hs = ip.levels.flatMap(lv => lv.bosses.flatMap(b => b.attacks.map(a => a.hourIdx)));
        assert.ok(hs.length >= 2 && hs.every(h => h >= night.fromIdx), `ブロックの頭より前に置かれている: ${JSON.stringify(hs)}`);
        assert.equal(rbd2.attackCountIn(ip, night), hs.filter(h => h <= night.toIdx).length);
        assert.ok(!ip.levels.flatMap(lv => lv.bosses.flatMap(b => b.attacks.map(a => a.memberName))).includes('夕方だけ'), '夜のブロックに夕方だけの人が居る');
        assert.ok(/myResv = window\.raidBlocksDomain\.scopeReservations\(myResv, pubScope\);/.test(home), '予約を範囲に絞っていない (選んだブロック)');
        assert.ok(/const scoped = \(pubScope && window\.raidBlocksDomain\) \? window\.raidBlocksDomain\.scopePlan\(prev\.plan, pubScope\) : prev\.plan;\s*\n\s*const d = dd\.diffPlans\(scoped, plan\);/.test(home), 'L3 の前回を範囲に絞っていない (選んだブロック)');
        assert.ok(/const imgPlan = \(_opsLastPlan\.blockScope && window\.raidBlocksDomain\) \? window\.raidBlocksDomain\.scopePlan\(_opsLastPlan, _opsLastPlan\.blockScope\) : _opsLastPlan;/.test(html) && /_renderPlanToImageTimetable\(imgPlan,/.test(html) && /_renderPlanToImage\(imgPlan\)/.test(html), '共有画像を範囲に絞っていない');
        // 古い版 (2 を読む端末) は 3 の配信を読まない
        const cg = globalThis.clientGateDomain;
        assert.equal(cg.planReadable({ planSchema: 3, supportedSchema: 2 }).readable, false, '古い端末が blockScope の配信を読めてしまう');
        assert.equal(cg.planReadable({ planSchema: 2, supportedSchema: 3 }).readable, true, '新しい端末が前の版の配信を読めない');
    });

    test('★ 配線: 🧱 時間アンケートをブロックで (③-b) — 参加可能時間はブロックのチップで選ぶ / 押すと丸ごと ON・OFF / 保存は時間帯のまま / ホームの帯にブロック名', () => {
        const html = _grRd('index.html').split(String.fromCharCode(13)).join('');
        const ui = html.match(/function _renderAvailUI\(\) \{[\s\S]*?\n        \}\n/)?.[0] || '';
        assert.ok(ui, '_renderAvailUI が無い');
        // 区切りはシーズンのもの (無ければ既定) / 状態はドメイン / 1 時間刻みの登録は「一部」
        assert.ok(/const blocks = rbd \? rbd\.blocksOfSeason\(_availUI\.season\) : \[\];/.test(ui), 'ブロックを (開いたときに取り直した) シーズンから読んでいない');
        assert.ok(/const states = rbd \? rbd\.blockStates\(blocks, slotKeys\) : \[\];/.test(ui), 'ON の具合をドメインで出していない');
        assert.ok(/class="avail-blk" data-state="\$\{st\.state\}"/.test(ui) && /onclick="_availToggleBlock\(\$\{st\.idx\}\)"/.test(ui), 'ブロックのチップが無い');
        assert.ok(/`一部 \$\{st\.on\}\/\$\{st\.hours\}時間`/.test(ui), '一部の見せ方が無い');
        assert.ok(/data-now="1"/.test(ui), 'いまのブロックの印が無い');
        // タイムライン (24 セルのなぞり) は無くなった。プリセットは 2 つ
        assert.ok(!/availCells|avail-cell\b|_availAttachInteraction|labelIndices/.test(html), 'タイムラインの名残がある');
        assert.ok(!/'awake'|'except-late'/.test(html), '古いプリセットが残っている');
        assert.ok(/🧱 ブロックで選びます。1 時間でも出られるブロックを ON に。/.test(html), 'モーダルの説明が古い');
        // 押す: 全部 ON なら OFF、それ以外は丸ごと ON。保存は従来の _availScheduleSave (時間帯 'hXX')
        const tg = html.match(/function _availToggleBlock\(i\) \{[\s\S]*?\n        \}\n/)?.[0] || '';
        assert.ok(/const next = new Set\(rbd\.toggleBlock\(keys, b, st\.state !== 'on'\)\);/.test(tg), '押したときの反転が違う');
        assert.ok(/_availUI\.slots = HOUR_ORDER\.map\(h => next\.has\(_hourKey\(h\)\)\);\s*\n\s*_renderAvailUI\(\);\s*\n\s*_availScheduleSave\(\);/.test(tg), '24 個の bool に戻して保存していない');
        // 開くたびに DB からシーズンを取り直す (運営が区切りを変えたあとに古い区切りで保存しない)。seasonStore は触らない (全タブのキャッシュを飛ばさない・fail-open しない)。
        // 取れなかったら blocksReady=false のまま = チップ・プリセット・解除のどれも保存させない (Codex指摘)
        const settings = html.match(/async function renderMyAvailabilitySettings\(identity\) \{[\s\S]*?\n        \}\n/)?.[0] || '';
        assert.ok(/_availUI\.season = null;\s*\n\s*_availUI\.blocksReady = false;/.test(settings), '開くたびに状態を戻していない');
        assert.ok(/const fresh = \(typeof window\.supabaseLoadActiveSeasonWithBosses === 'function'\) \? await window\.supabaseLoadActiveSeasonWithBosses\(\) : null;\s*\n\s*if \(ses !== _availUI\.session\) return;\s*\n\s*if \(fresh\) \{ _availUI\.season = fresh\.season \|\| null; _availUI\.blocksReady = true; \}/.test(settings), 'DB から取り直していない / 取れたときだけ ready にしていない (9a: 待っている間に別の人を開いたら捨てる)');
        assert.ok(!/seasonStore\.invalidate\(\)/.test(settings) && !/lastLoadFailed/.test(html), 'モーダルが seasonStore を無効化している / 使わなくなった口が残っている');
        assert.ok(/rbd\.blocksOfSeason\(_availUI\.season\)/.test(ui) && /rbd\.blocksOfSeason\(_availUI\.season\)/.test(tg), '取り直したシーズンの区切りを使っていない');
        assert.equal((ui.match(/\$\{_availUI\.blocksReady \? '' : 'disabled'\}/g) || []).length, 3, 'チップ・プリセット・解除 の 3 つを disabled にしていない');
        assert.ok(/if \(!_availUI\.blocksReady\) \{ showNotification\(/.test(tg), '区切りを読めていないのに押せる');
        const rm = html.match(/function _availRemoveRange\(fromIdx, toIdx\) \{[\s\S]*?\n        \}\n/)?.[0] || '';
        assert.ok(/if \(!_availUI\.blocksReady\) \{ showNotification\(/.test(rm), '解除は止めていない (見せるだけ、を破る)');
        assert.ok(/<button type="button" \$\{_availUI\.blocksReady \? '' : 'disabled'\} onclick="_availRemoveRange/.test(ui), '解除が div のまま');
        assert.ok(/onclick="renderMyAvailabilitySettings\(_availTarget\(\)\)"/.test(ui), '取り直すボタンが無い');
        const preset = html.match(/function _availApplyPreset\(preset\) \{[\s\S]*?\n        \}\n/)?.[0] || '';
        assert.ok(/if \(!_availUI\.blocksReady\) \{ showNotification\(/.test(preset), 'プリセットも止めていない');
        // 「一部」を押すと全時間 ON になることを常に書く / aria-pressed (true / false / mixed) / プリセットは button
        assert.ok(/押すとそのブロックの全時間が ON になります/.test(ui) && /押すとこのブロックの全時間が ON/.test(ui), '「一部」の説明が無い');
        assert.ok(/aria-pressed="\$\{pressed\}"/.test(ui) && /st\.state === 'partial' \? 'mixed'/.test(ui), 'aria-pressed が無い');
        assert.ok(/<button type="button" class="avail-preset-pill"/.test(ui) && !/<div class="avail-preset-pill"/.test(ui), 'プリセットが div のまま');
        // 残骸なし / 運営が区切りを保存したらシーズンのキャッシュを捨てる
        assert.ok(!/dragging: false|dragMode: null|availPulseDot|タイムライン \(なぞって選択\) =====\s*\*\/\s*\n\s*\}/.test(html), 'タイムラインの残骸がある');
        assert.ok(/_opsPlanBlockIdx = null;[^\n]*\n\s*seasonStore\.invalidate\(\);/.test(html), '区切りを保存したあとシーズンのキャッシュを捨てていない');
        // ホームの帯: 下のラベルはブロック名 (ドメインが無ければ時刻)
        const strip = html.match(/async function renderMyAvailStrip\(identity\) \{[\s\S]*?\n        \}\n/)?.[0] || '';
        assert.ok(/blocks\.map\(b => `<span title="\$\{escapeHtml\(b\.label\)\}" style="flex:\$\{b\.slots\.length\};/.test(strip), '帯のラベルがブロック名になっていない');
        assert.ok(/: \[5, 9, 13, 17, 21, 0\]\.map\(h =>/.test(strip), 'ドメインが無いときの時刻ラベルが無い');
        // CSS: チップの状態はトークンで
        const css = html.slice(html.indexOf('<style'), html.lastIndexOf('</style>'));
        assert.ok(/\.avail-blk\[data-state="on"\] \{ background: var\(--ok-bg\); border-color: var\(--ok-solid\); \}/.test(css) && /\.avail-blk\[data-state="partial"\] \{ border-style: dashed;/.test(css), 'チップの CSS が無い');
    });

    test('★ 配線: 📅 きょうの凸 (③-c) — カードは配信プランの直後 (data-span) / 配信あり・なし・名乗りなし の 3 経路で描く・消す / 材料は使い回す / 判定はドメイン', () => {
        const html = _grRd('index.html').split(String.fromCharCode(13)).join('');
        assert.ok(/<div class="dc-card" data-span="6" id="myTodayBlocksCard" style="display:none;">/.test(html), 'カードが無い (data-span 付き)');
        assert.ok(html.indexOf('id="myPublishedPlanCard"') < html.indexOf('id="myTodayBlocksCard"') && html.indexOf('id="myTodayBlocksCard"') < html.indexOf('id="myPushCheckCard"'), 'カードの位置が配信プランの直後でない');
        const pub = html.match(/async function renderMyPublishedPlan\(identity\) \{[\s\S]*?\n        \}\n/)?.[0] || '';
        assert.ok(/if \(!identity\?\.id\) \{ card\.style\.display = 'none'; renderMyTodayBlocks\(null\); renderMyMocksReadonly\(null\); return; \}/.test(pub), '名乗りなしで消していない (きょうの凸 + 登録された模擬)');
        assert.ok(/if \(!pub\?\.plan\) \{\s*\n\s*card\.style\.display = 'none';\s*\n\s*renderMyTodayBlocks\(identity\);/.test(pub), '配信なしでも描いていない');
        assert.ok(/_renderMyPubBody\(\);\s*\n\s*card\.style\.display = '';\s*\n\s*renderMyTodayBlocks\(identity\);/.test(pub), '配信ありで描いていない');
        assert.ok(/myAttackRows = Array\.isArray\(atks\) \? atks : \[\];/.test(pub) && /resv: myResv, todayAttacks, myAttackRows,\s*\n\s*pubs: pubList, pubKey: pubSel \? pubSel\.key : null, pubRows, decidedCurrent: !!decRow, rowsAt \};/.test(pub), 'その日の凸の行を使い回していない / ブロックごとの配信を状態に持っていない');
        const fn = html.match(/async function renderMyTodayBlocks\(identity\) \{[\s\S]*?\n        \}\n/)?.[0] || '';
        assert.ok(fn, 'renderMyTodayBlocks が無い');
        assert.ok(/rbd\.todayRows\(\{ blocks, nowHour, plans, viewerId: identity\.id, attacks: rows \|\| \[\], hourOfIso: _planJstHour \}\)/.test(fn), '判定をドメインに任せていない');
        assert.ok(/String\(_myPubState\.viewerId\) === String\(identity\.id\) && String\(_myPubState\.seasonId\) === String\(season\.id\)/.test(fn), '別人・別シーズンの配信を使ってしまう');
        assert.ok(/Array\.isArray\(st\?\.myAttackRows\) \? st\.myAttackRows\s*\n\s*: \(typeof window\.supabaseLoadMyAttacks === 'function' \? await window\.supabaseLoadMyAttacks\(identity\.id, season\.id, season\.hard_date\) : \[\]\);/.test(fn), '配信カードの凸の行を使い回さず二度読む / 無いときに読まない');
        assert.ok(/if \(seq !== _todayBlocksSeq\) return;/.test(fn), '世代ガードが無い');
        // Codex指摘: 消す経路でも世代を進める / 完了時に名乗っている人も照合 / 互換ゲートで読めない配信のときも消す
        assert.ok(/const seq = \+\+_todayBlocksSeq;\s*\n\s*if \(!identity\?\.id \|\| !rbd\) \{ card\.style\.display = 'none'; return; \}/.test(fn), '名乗りなしの経路で世代を進めていない (前の人の遅れた描画が出る)');
        assert.ok(/if \(seq !== _todayBlocksSeq \|\| String\(getCurrentIdentity\(\)\?\.id \?\? ''\) !== String\(identity\.id\)\) return;/.test(fn), '完了時に名乗っている人を照合していない');
        assert.ok(/renderMyNextAction\(identity\);\s*\n\s*\}\s*\n\s*renderMyTodayBlocks\(null\); renderMyMocksReadonly\(null\);   \/\/ 📅 古い指示を残さない/.test(pub), '互換ゲートで読めない配信のときに消していない (きょうの凸 + 登録された模擬)');
        assert.ok(/まだ決まっていません \(運営がこのブロックの前に配信します\)/.test(fn) && /このブロックに割当はありません/.test(fn) && /凸なし/.test(fn), '3 つの空の言い方が無い');
        assert.ok(/outline:2px solid var\(--ops-solid\)/.test(fn), 'いまのブロックの枠が無い');
        assert.ok(/時刻の分からない凸 \$\{t\.unknownTime\.length\} 件は行に出ません/.test(fn), '時刻の分からない凸を黙って消している');
        assert.ok(!/#[0-9A-Fa-f]{6}/.test(fn.replace(/'#7A7C81'/g, '')), '色の直値 (灰色の既定以外) がある');
    });

    test('★ 🧱 段階 2 凸数のドメイン: normalizeCounts (ON のブロックだけ・1〜3・合計 3 まで) / stepCount / countsLabel / capsOf (済んだ凸を引く)', () => {
        const d = globalThis.raidBlocksDomain;
        const blocks = d.blocksOfSeason(null);   // 既定 6 つ (朝 5-8 / 午前 9-12 / 午後 13-16 / 夕方 17-20 / 夜 21-0 / 深夜 1-4)
        const on = (...ks) => ks.flatMap(k => blocks.find(b => b.name === k).slots);
        const slots = on('朝', '夕方');
        assert.equal(d.countKey(blocks[0]), '5-8'); assert.equal(d.countKey(null), '');
        assert.deepEqual(d.normalizeCounts({ '5-8': 1, '17-20': 2 }, blocks, slots), { '5-8': 1, '17-20': 2 });
        assert.deepEqual(d.normalizeCounts({ '5-8': 1, '21-0': 2 }, blocks, slots), { '5-8': 1 }, 'OFF のブロックの凸数を残している');
        assert.deepEqual(d.normalizeCounts({ '5-8': 3, '17-20': 2 }, blocks, slots), { '5-8': 3 }, '合計 3 を超えている (ブロックの順で詰める)');
        assert.deepEqual(d.normalizeCounts({ '5-8': 2, '17-20': 2 }, blocks, slots), { '5-8': 2, '17-20': 1 });
        assert.equal(d.normalizeCounts({ '5-8': 0, '17-20': 'x' }, blocks, slots), null);
        assert.equal(d.normalizeCounts([1, 2], blocks, slots), null); assert.equal(d.normalizeCounts(null, blocks, slots), null);
        assert.deepEqual(d.normalizeCounts({ '5-8': 1, '9-12': 1 }, blocks, ['h08']), { '5-8': 1 }, '一部だけ ON (1 時間) のブロックも ON として数える');
        // stepCount: + / − / 0 で消える (おまかせ) / 合計 3 で + しない / OFF のブロックは何もしない
        let c = d.stepCount(null, blocks, slots, 0, 1); assert.deepEqual(c, { '5-8': 1 });
        c = d.stepCount(c, blocks, slots, 3, 1); c = d.stepCount(c, blocks, slots, 3, 1); assert.deepEqual(c, { '5-8': 1, '17-20': 2 });
        assert.deepEqual(d.stepCount(c, blocks, slots, 3, 1), { '5-8': 1, '17-20': 2 }, '合計 3 なのに増やしている');
        assert.deepEqual(d.stepCount(c, blocks, slots, 0, -1), { '17-20': 2 }, '0 にしたのに鍵が残る');
        assert.deepEqual(d.stepCount(c, blocks, slots, 4, 1) /*夜 OFF*/, { '5-8': 1, '17-20': 2 }, 'OFF のブロックに凸数を入れている');
        assert.equal(d.stepCount({ '5-8': 1 }, blocks, slots, 0, -1), null);
        assert.equal(d.countsLabel({ '17-20': 2, '5-8': 1 }, blocks), 'A 朝 1 · D 夕方 2', 'ブロックの順に並べていない (文字つき)');
        assert.equal(d.countsLabel(null, blocks), ''); assert.equal(d.countsTotal({ a: 1, b: 2 }), 3);
        // capsOf: max = 凸数 − そのブロックで済んだ凸 (朝に 1 凸済み → 朝の残り 0 / 夕方は 2)
        assert.deepEqual(d.capsOf({ '5-8': 1, '17-20': 2 }, blocks, [7, 13]), [{ fromIdx: 0, toIdx: 3, max: 0 }, { fromIdx: 12, toIdx: 15, max: 2 }]);
        assert.deepEqual(d.capsOf(null, blocks, []), []); assert.deepEqual(d.capsOf({ '1-2': 1 }, blocks, []), [], '合わない鍵 (区切りが変わった) を上限にしている');
        // 生の値でも合計 3 をブロックの順で守る (朝 3 + 午前 3 → 朝 3 だけ) (Codex指摘)
        assert.deepEqual(d.capsOf({ '5-8': 3, '9-12': 3 }, blocks, []), [{ fromIdx: 0, toIdx: 3, max: 3 }], '合計 3 を超える上限を渡している');
        assert.deepEqual(d.capsOf({ '5-8': 2, '17-20': 2 }, blocks, []), [{ fromIdx: 0, toIdx: 3, max: 2 }, { fromIdx: 12, toIdx: 15, max: 1 }]);
    });
    test('★ 配線: 🧱 段階 2 凸数の保存と読み込み (SQL 53) / ⏳隙間時間型の撤廃', () => {
        const html = _grRd('index.html').split(String.fromCharCode(13)).join('');
        const client = _grRd('js', 'supabase-client.js').split(String.fromCharCode(13)).join('');
        const sql = _grRd('supabase', '53_block_counts.sql').split(String.fromCharCode(13)).join('');
        assert.ok(/ALTER TABLE availability_confirmations ADD COLUMN IF NOT EXISTS block_counts JSONB;/.test(sql), 'SQL 53 が無い');
        assert.ok(/'53_block_counts',\s*\n\s*EXISTS \(SELECT 1 FROM information_schema\.columns WHERE table_schema = 'public' AND table_name = 'availability_confirmations' AND column_name = 'block_counts'\)/.test(_grRd('supabase', '99_check_applied.sql').split(String.fromCharCode(13)).join('')), '99 に 53 の判定が無い');
        // 保存: 難しい / 空 は NULL・53 未適用は列を外して保存し、落としたことを返す
        const cf = client.match(/window\.supabaseConfirmAvailability = async function[\s\S]*?\n\};\n/)?.[0] || '';
        assert.ok(/row\.block_counts = \(!unavailable && blockCounts && typeof blockCounts === 'object' && !Array\.isArray\(blockCounts\) && Object\.keys\(blockCounts\)\.length\) \? blockCounts : null;/.test(cf));
        assert.ok(/if \(error && _isMissingColumnErr\(error, 'block_counts'\)\) \{\s*\n\s*blockCountsDropped = row\.block_counts != null;\s*\n\s*delete row\.block_counts;/.test(cf) && /return \{ blockCountsDropped \};/.test(cf), '53 未適用で落とす / 落としたことを返す、ができていない');
        assert.ok(cf.indexOf("_isMissingColumnErr(error, 'block_counts')") < cf.indexOf("_isMissingColumnErr(error, 'slots_snapshot')"), '外す順が違う (53 → 37 追補)');
        assert.ok(/_one\('confirmed_at, unavailable, slot_count, slots_snapshot, block_counts'\)/.test(client) && /_all\('player_id, confirmed_at, unavailable, slot_count, slots_snapshot, block_counts'\)/.test(client), '確認の行から凸数を読んでいない');
        assert.ok(/if \(uErr && _isMissingColumnErr\(uErr, 'block_counts'\)\) \{ withCounts = false;/.test(client), '盤面ローダが 53 未適用で落ちる');
        assert.ok(/if \(c\.unavailable\) \{ unavailableIds\.add\(Number\(c\.player_id\)\); return; \}/.test(client), '「今回は難しい」の除外が壊れた (全部の行を読むようにしたので unavailable を見る)');
        assert.ok(!/supabaseUpdateAvailabilityPrefs|supabaseLoadAvailabilityPrefs/.test(client + html), '⏳隙間時間型を読む・書く経路が残っている');
        // ⏳ flex_time の列はもう select しない (通知状況の一覧・盤面ローダ)。flexTime は常に false で返す (Codex指摘: 一覧に「+⏳」が残っていた)
        assert.ok(!/'[^'\n]*flex_time[^'\n]*'/.test(client) && !/flexTime: !!p\.flex_time/.test(client), 'players.flex_time をまだ読んでいる (列の指定に残っている)');
        // シート: 凸数の欄・±・開いたときだけ確認の行から取り込む・確認で渡す・確認したあとに変えたら知らせる
        const ui = html.match(/\n        function _renderAvailUI\(\) \{[\s\S]*?\n        \}\n/)?.[0] || '';
        assert.ok(/_availUI\.counts = rbd \? rbd\.normalizeCounts\(_availUI\.counts, blocks, slotKeys\) : null;/.test(ui) && /\$\{countsHtml\}/.test(ui), 'シートに凸数の欄が無い');
        assert.ok(/onclick="_availStepCount\(\$\{st\.idx\}, -1\)"/.test(ui) && /onclick="_availStepCount\(\$\{st\.idx\}, 1\)"/.test(ui) && /\$\{cTotal >= 3 \? 'disabled' : ''\}/.test(ui), '± / 合計 3 の上限が無い');
        assert.ok(/_availUI\.counts = rbd\.stepCount\(_availUI\.counts, blocks, keys, Number\(i\), Number\(delta\)\);/.test(html));
        assert.ok(/_availUI\.counts = null;\s*\n\s*_availUI\.countsPending = true;/.test(html) && /if \(_availUI\.countsPending\) \{/.test(html), '開いたときだけ確認の行から凸数を取り込む、ができていない');
        // 本人が −/+ を押したら、遅れて届いた確認の行で上書きしない (Codex指摘)
        const step = html.match(/function _availStepCount\(i, delta\) \{[\s\S]*?\n        \}\n/)?.[0] || '';
        assert.ok(/_availUI\.counts = rbd\.stepCount\([^\n]*\n\s*_availUI\.countsPending = false;/.test(step), '−/+ のあとも確認の行の取り込みを待っている (押した凸数が上書きされる)');
        const cfm = html.match(/\n        async function handleConfirmAvailability\(unavailable\) \{[\s\S]*?\n        \}\n/)?.[0] || '';
        assert.ok(/counts = \(!unavailable && rbd\) \? rbd\.normalizeCounts\(countsAtPress, rbd\.blocksOfSeason\(op\.season \|\| ctx\.season\), slots\) : null;/.test(cfm), '凸数を保存した時間帯で詰め直していない');
        assert.ok(/slots: unavailable \? null : slots, blockCounts: counts,\s*\n\s*actorName: op\.actorName \}\);/.test(cfm) && /countsDropped = !!\(res && res\.blockCountsDropped\);/.test(cfm), '確認で凸数を渡していない / 落ちたことを見ていない');
        assert.ok(/\.\.\.\(countsDropped \? \{\} : \{ block_counts: counts \}\)/.test(cfm), '落ちたときに凸数を持つ (「凸数を変えました」が出続ける)');
        assert.ok(/const changedCounts = !!\(c && !c\.unavailable && 'block_counts' in c && _cKey\(c\.block_counts\) !== _cKey\(_availUI\.counts\)\);/.test(html), '確認したあとに凸数を変えたことを知らせていない');
        assert.ok(!/myAvailFlexTime|⏳ 隙間時間型 \(時間の約束はできないが3凸はする\)/.test(html), '⏳隙間時間型のスイッチが残っている');
    });
    test('📘 readonlyRows (🧱 段階 1・2026-10-22): 属性ごとに 編成① / ② を並べ、無い属性は missing / 大文字の属性も読む / 空の行は無視 / damageOf で代表値', () => {
        const d = globalThis.mockIntakeDomain;
        const rows = [
            { attribute: 'wind', slot: 2, characters: ['a', 'b'], damage_b: 21.4 },
            { attribute: 'WIND', slot: 1, characters: ['c', 'd', 'e', 'f', 'g'], damage_b: 28.1 },
            { attribute: 'fire', slot: 1, characters: [], damage_b: 0 },        // 空 = 無いのと同じ
            { attribute: 'water', slot: 1, characters: null, damage_b: 19.8 },  // 編成なし・ダメージだけ
        ];
        const out = d.readonlyRows(rows);
        assert.deepEqual(out.map(r => [r.key, r.name, r.missing, r.teams.map(x => [x.slot, x.team.length, x.dmgB])]), [
            ['fire', '灼熱', true, []], ['water', '水冷', false, [[1, 0, 19.8]]], ['electric', '電撃', true, []], ['iron', '鉄甲', true, []], ['wind', '風圧', false, [[1, 5, 28.1], [2, 2, 21.4]]],
        ], '属性ごとの行が違う');
        assert.equal(d.readonlyRows(rows, { damageOf: () => 7 })[4].teams[0].dmgB, 7, 'damageOf を使っていない');
        assert.deepEqual(d.readonlyRows(null).map(r => r.missing), [true, true, true, true, true]);
        assert.deepEqual(d.readonlyRows([{ attribute: 'iron', slot: 1, characters: ['x', null, 'y'], damage_b: 3 }])[3].teams[0].team, ['x', 'y'], '空のキャラを落としていない');
    });
