    test('★ バーストの色を読める形にして使う (_burstInk / _burstOnBg)', () => {
        // ★ 色をそのまま文字にしない。B2 の黄色 #F2B705 は白地でも白文字でも 1.8:1 で読めない。
        //   「B2 のときだけ黒」と手で書き分けていた箇所もあったが、色表を変えた瞬間に破綻する
        const html = _grRd('index.html').split(String.fromCharCode(13)).join('');
        const cut = (name) => {
            const i = html.indexOf(`function ${name}(`);
            assert.ok(i > 0, `${name} が無い`);
            let d = 0, started = false;
            for (let k = html.indexOf('{', i); k < html.length; k++) {
                if (html[k] === '{') { d++; started = true; }
                else if (html[k] === '}') { d--; if (started && !d) return html.slice(i, k + 1); }
            }
            throw new Error(`${name} の終端が分からない`);
        };
        const helpers = ['_HEX6', '_BURST_BG_FALLBACK', '_burstLin', '_burstLum', '_burstRgb']
            .map(n => html.match(new RegExp(`const ${n} = [^\n]*`))?.[0])
            .join('\n');
        assert.ok(!/undefined/.test(helpers), `補助の定義を切り出せない: ${helpers}`);
        // ★ 地はテーマで変わる。themeVar を差し替えて**両方のテーマで**動かす
        const build = (groundHex) => new Function('__bg',
            `${helpers}\nconst themeVar = () => __bg;\n${cut('_burstBg')}\n${cut('_burstInk')}\n${cut('_burstOnBg')}\n${cut('_burstTint')}`
            + '\nreturn { _burstInk, _burstOnBg, _burstTint, _burstBg };')(groundHex);
        const css = html.slice(html.indexOf('<style'), html.lastIndexOf('</style>'));
        const tokOf = (from, to, name) => css.slice(css.indexOf(from), css.indexOf(to, css.indexOf(from)))
            .match(new RegExp('--' + name + ':\\s*(#[0-9A-Fa-f]{6});'))?.[1];
        const s1Of = (from, to) => tokOf(from, to, 'burst-bg');
        const GROUND = {
            ライト: s1Of(':root, :root[data-theme="light"]', ':root[data-theme="dark"]'),
            ダーク: s1Of(':root[data-theme="dark"]', '/* === マーブル'),
        };
        assert.ok(GROUND.ライト && GROUND.ダーク, `地のトークンを読めない: ${JSON.stringify(GROUND)}`);
        const F = build(GROUND.ライト);

        const lin = (n) => { const v = n / 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
        const lum = (h) => 0.2126 * lin(parseInt(h.slice(1, 3), 16)) + 0.7152 * lin(parseInt(h.slice(3, 5), 16))
            + 0.0722 * lin(parseInt(h.slice(5, 7), 16));
        const onWhite = (h) => 1.05 / (lum(h) + 0.05);

        // 端: 白地なら黒文字、黒地なら白文字
        assert.equal(F._burstInk('#FFFFFF'), '#000000', '白地に白文字を選んでいる');
        assert.equal(F._burstInk('#000000'), '#FFFFFF', '黒地に黒文字を選んでいる');
        assert.equal(F._burstInk('こわれた値'), '#FFFFFF', '色でない値で落ちている');
        assert.equal(F._burstOnBg('こわれた値'), '#8A9097', '色でない値で落ちている');

        // ★ 色表の4色すべてで、白地の文字が 4.5:1 以上・色地の文字が 4.5:1 以上
        const src = html.match(/const TE_BURST_COLOR = \{[^}]*\}/)?.[0] || '';
        const colors = Object.fromEntries([...src.matchAll(/'?([A-ZΛ0-9]+)'?:\s*'(#[0-9A-Fa-f]{6})'/g)]
            .map(m => [m[1], m[2]]));
        assert.equal(Object.keys(colors).length, 4, `色表が読めない: ${src}`);
        const ratio = (x, y) => (Math.max(lum(x), lum(y)) + 0.05) / (Math.min(lum(x), lum(y)) + 0.05);
        // ★ バッジは白いカードだけでなく、**ホバー中の行やタイル**の上にも載る (Codex指摘)
        // ★ 地は --burst-bg というトークンになった (ホバー色もトークン)。
        //   --burst-bg は、実際のホバー色のうち**バッジにいちばん厳しいもの**であること。
        //   厳しい = ライトなら「いちばん暗い」/ ダークなら「いちばん明るい」(向きが逆になる)
        assert.ok(/function _burstBg\(\) \{ return themeVar\('burst-bg'/.test(html),
            'バッジの地をトークンから読んでいない');
        const hoverToks = [...new Set([...html.matchAll(/this\.style\.background='var\(--([a-z0-9-]+)\)'/g)].map(m => m[1]))];
        assert.ok(hoverToks.length >= 2, `ホバー色を拾えない: ${JSON.stringify(hoverToks)}`);
        for (const [mode, g] of Object.entries(GROUND)) {
            const from = mode === 'ライト' ? ':root, :root[data-theme="light"]' : ':root[data-theme="dark"]';
            const to = mode === 'ライト' ? ':root[data-theme="dark"]' : '/* === マーブル';
            const others = hoverToks.map(t => tokOf(from, to, t)).filter(Boolean);
            assert.ok(others.length >= 2, `${mode}: ホバー色のトークンを解決できない`);
            for (const h of others) {
                // 「地から遠いほど厳しい」= バッジの色は地に寄せて作るので、地が端から離れるほど余裕が無い
                const far = (x) => Math.abs(lum(x) - lum(mode === 'ライト' ? '#FFFFFF' : '#000000'));
                assert.ok(far(h) <= far(g) + 1e-9,
                    `${mode}: ${g} よりバッジに厳しいホバー色 ${h} がある — その上に載らないか確かめること`);
            }
        }
        const BG = GROUND.ライト;
        for (const [mode, GB] of Object.entries(GROUND)) {
          const F = build(GB);
          for (const [b, c] of Object.entries(colors)) {
            // ① 薄く色を敷いた地 (CSS の `${色}1A`) に文字を置く場合
            //    ★ 純白で測ると足りない — 実際の地はほんのり色が付いている (Codex指摘)
            const bg = F._burstTint(c);
            assert.match(bg, /^#[0-9a-f]{6}$/, `${b} の薄い地が色になっていない: ${bg}`);
            const t = F._burstOnBg(c, bg);
            assert.match(t, /^#[0-9a-f]{6}$/, `${b} の文字色が色になっていない: ${t}`);
            assert.ok(ratio(t, bg) >= 4.5, `${mode}: ${b} の文字が薄い地で読めない (${ratio(t, bg).toFixed(2)}:1)`);
            // ② 地が透明 (枠だけ) の場合は、その下のいちばん暗い地に対して
            const edge = F._burstOnBg(c, GB);
            assert.ok(ratio(edge, GB) >= 4.5, `${mode}: ${b} の枠がホバー中に読めない (${ratio(edge, GB).toFixed(2)}:1)`);
            assert.ok(ratio(edge, mode === 'ライト' ? '#FFFFFF' : '#17191D') >= 4.5, `${mode}: ${b} の枠がカードの上で読めない`);
            // ③ 色をそのまま地にする場合
            assert.ok(ratio(F._burstInk(c), c) >= 4.5, `${mode}: ${b} の地に載せる文字が読めない (${ratio(F._burstInk(c), c).toFixed(2)}:1)`);
          }
        }
        // ★ 色の上に白を決め打ちしない / 「B2 だけ黒」と書き分けない
        assert.ok(!/background:\$\{o\.color\};color:#fff/.test(html), 'アイコンピッカーで白を決め打ちしている');
        assert.ok(!/background:\$\{color\};color:#fff/.test(html), 'バーストピッカーで白を決め打ちしている');
        assert.ok(!/=== 'B2' \? '#14161A'/.test(html), '「B2 だけ黒」と手で書き分けている');
        assert.ok(!/=== 'B2' \? ' dark'/.test(html), '「B2 だけ暗い字」と手で書き分けている');
        assert.ok(!/\.te-band\.dark \{/.test(html), '手書き分け用の CSS が残っている');

        // ★ 関数が正しくても、呼ぶ側が地を渡していなければ意味が無い。
        //   _burstOnBg は**必ず地を渡して**呼ぶ (純白の決め打ちは薄い地で足りない)
        const calls = [...html.matchAll(/_burstOnBg\(((?:[^()]|\([^()]*\))*)\)/g)]
            .map(m => m[1]).filter(x => !x.startsWith('hex'));
        assert.ok(calls.length >= 5, `_burstOnBg の呼び出しを拾えない: ${calls.length}`);
        for (const args of calls) {
            assert.ok(args.includes(','), `地を渡さずに呼んでいる: _burstOnBg(${args})`);
            // ★ 渡す地は _burstTint(色) か _burstBg() のどちらか。**色を書かない** —
            //   バッジはホバー中の行やタイルの上にも載るし、地はテーマで入れ替わる
            const bg = args.slice(args.indexOf(',') + 1).trim();
            assert.ok(bg.startsWith('_burstTint(') || bg === '_burstBg()',
                `地の指定が決め打ちになっている: _burstOnBg(${args})`);
        }
        // 色を薄く敷いた地なら _burstTint を渡す (白の決め打ちでは足りない)
        for (const m of html.matchAll(/background:\$\{([^}]+)\}1A;color:\$\{_burstOnBg\(((?:[^()]|\([^()]*\))*)\)\}/g)) {
            assert.ok(m[2].includes('_burstTint('), `薄い地なのに地を渡していない: ${m[0].slice(0, 80)}`);
        }
        // ★ 薄い地の濃さは CSS の `1A` と同じでなければ、測る地が実物とずれる
        assert.ok(/background:\$\{[^}]+\}1A;/.test(html), 'CSS の薄い地が 1A でなくなっている');
        assert.equal(F._burstTint('#000000', '#FFFFFF'), '#e5e5e5',
            '薄い地の濃さが CSS の 1A (10.2%) と合っていない');
        assert.equal(F._burstTint('#FFFFFF', '#FFFFFF'), '#ffffff');
        // 既定の地は _BURST_BG (ホバー中) — 白を決め打ちしない
        assert.notEqual(F._burstTint('#FFFFFF'), '#ffffff', '既定の地が白のままになっている');
    });
    test('★ 色のトークン: ライトとダークが同じ顔ぶれで、文字は両方 4.5:1 以上', () => {
        // ★ 以前ダークモードを断念した原因は「色を直に書いていた」こと。トークンに寄せ、
        //   文字の色は**計算で**地に合わせる。ここが崩れると片方のテーマで読めなくなる
        const html = _grRd('index.html').split(String.fromCharCode(13)).join('');
        const block = (sel) => html.match(new RegExp(sel.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*\\{([^}]*)\\}'))?.[1] || '';
        const vars = (sel) => Object.fromEntries([...block(sel).matchAll(/--([a-z0-9-]+):\s*([^;]+);/g)]
            .map(m => [m[1], m[2].trim()]));
        const L = vars(':root, :root[data-theme="light"]');
        const Dk = vars(':root[data-theme="dark"]');
        assert.ok(Object.keys(L).length >= 40, `ライトのトークンが少なすぎる: ${Object.keys(L).length}`);
        assert.deepEqual(Object.keys(Dk).sort(), Object.keys(L).sort(),
            'ライトとダークでトークンの顔ぶれが違う (片方だけ定義された色は、もう片方で必ず崩れる)');

        const lin = (n) => { const v = n / 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
        const lum = (h) => { const c = [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));
            return 0.2126 * lin(c[0]) + 0.7152 * lin(c[1]) + 0.0722 * lin(c[2]); };
        const ratio = (a, b) => { const x = lum(a) + 0.05, y = lum(b) + 0.05; return Math.max(x, y) / Math.min(x, y); };
        const hex6 = /^#[0-9A-Fa-f]{6}$/;

        for (const [mode, t] of [['ライト', L], ['ダーク', Dk]]) {
            // ★ 文字の4段は、カードに対して 4.5:1 以上
            for (const k of ['t-ink', 't-strong', 't-body', 't-muted']) {
                assert.ok(hex6.test(t[k]), `${mode} --${k} が色になっていない: ${t[k]}`);
                const r = ratio(t[k], t.card);
                assert.ok(r >= 4.5, `${mode} --${k} がカードの上で読めない (${r.toFixed(2)}:1)`);
            }
            // ★ 状態・属性の色も、文字 / 薄い地 / 色地 の3通りすべてで 4.5:1 以上
            const roles = ['ops', 'ok', 'warn', 'bad', 'attr-fire', 'attr-water', 'attr-electric', 'attr-iron', 'attr-wind'];
            for (const k of roles) {
                assert.ok(hex6.test(t[k]), `${mode} --${k} が無い`);
                assert.ok(ratio(t[k], t.card) >= 4.5, `${mode} --${k} がカードの上で読めない`);
                assert.ok(ratio(t[`${k}-on`], t[`${k}-bg`]) >= 4.5, `${mode} --${k}-on が薄い地で読めない`);
                assert.ok(ratio(t[`${k}-ink`], t[`${k}-solid`]) >= 4.5, `${mode} --${k}-ink が色地で読めない`);
            }
            // ★ 属性の色と状態の色は**別のトークン**。同じ名前に寄せない
            assert.ok(t['attr-fire'] !== undefined && t.bad !== undefined, `${mode} 属性と状態が分かれていない`);
        }
        // ★ ダークの地はカードより暗い (カードが浮いて見えないと、線を引く羽目になる)
        assert.ok(lum(Dk.card) > lum(Dk.bg), 'ダークでカードが地より暗い');
        assert.ok(lum(L.card) > lum(L.bg), 'ライトでカードが地より暗い');
    });

    test('★ 文字と地の組が、ライトでもダークでも読める (実際に測る)', () => {
        // ★ 以前ダークを断念した原因はここ。「片方のテーマでしか成立しない組」が1つでもあれば落ちる。
        //   トークンの値だけでなく、**同じルールの中の color と background の組**を測る
        const html = _grRd('index.html').split(String.fromCharCode(13)).join('');
        const A = ':root, :root[data-theme="light"]', DK = ':root[data-theme="dark"]', B = '/* === マーブル';
        const varsOf = (from, to) => Object.fromEntries(
            [...html.slice(html.indexOf(from), html.indexOf(to)).matchAll(/--([a-z0-9-]+):\s*([^;]+);/g)]
                .map(m => [m[1], m[2].trim()]));
        const L = varsOf(A, DK), D = varsOf(DK, B);
        assert.ok(Object.keys(L).length > 30 && Object.keys(D).length > 30, 'トークンを読めない');
        const lin = (n) => { const v = n / 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
        const lum = (h) => { const c = [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));
            return 0.2126 * lin(c[0]) + 0.7152 * lin(c[1]) + 0.0722 * lin(c[2]); };
        const ratio = (a, b) => { const x = lum(a) + 0.05, y = lum(b) + 0.05; return Math.max(x, y) / Math.min(x, y); };
        const hex6 = /^#[0-9A-Fa-f]{6}$/;
        const css = html.slice(html.indexOf('<style'), html.lastIndexOf('</style>'));
        const body = css.slice(0, css.indexOf(A)) + css.slice(css.indexOf(B));
        const res = (v, T) => v.replace(/var\(--([a-z0-9-]+)\)/g, (w, k) => (T[k] !== undefined ? T[k] : w));
        let checked = 0; const ng = [];
        for (const [, sel, rule] of body.matchAll(/([^{}]*)\{([^{}]*)\}/g)) {
            const fg = (rule.match(/(?:^|;)\s*color\s*:\s*([^;]+)/) || [])[1];
            const bg = (rule.match(/(?:^|;)\s*background(?:-color)?\s*:\s*([^;]+)/) || [])[1];
            if (!fg || !bg) continue;
            for (const [mode, T] of [['ライト', L], ['ダーク', D]]) {
                const a = res(fg, T).trim(), b = res(bg, T).trim();
                if (!hex6.test(a) || !hex6.test(b)) continue;
                checked++;
                const r = ratio(a, b);
                if (r < 4.5) ng.push(`${mode} ${r.toFixed(2)}:1 ${sel.replace(/\s+/g, ' ').trim().slice(-40)} (${a} on ${b})`);
            }
        }
        assert.ok(checked >= 150, `測れた組が少なすぎる: ${checked}`);
        assert.deepEqual(ng, [], `片方のテーマで読めない組がある:\n  ${ng.join('\n  ')}`);
    });
    test('★ 色の直書きが増えていない (トークンへの置き換えの進み具合)', () => {
        // ★ 置き換えは段階的にやる。**増えていないこと**をここで見張る。
        //   直したら上限を下げること (下げ忘れると、戻ってしまっても気づけない)
        const html = _grRd('index.html').split(String.fromCharCode(13)).join('');
        const s0 = html.indexOf('<style'), s1 = html.lastIndexOf('</style>');
        assert.ok(s0 > 0 && s1 > s0, '<style> を切り出せない');
        let css = html.slice(s0, s1);
        // トークンの定義そのものは色を書いてよい
        const a = css.indexOf(':root, :root[data-theme="light"]');
        const b = css.indexOf('/* === マーブル');
        assert.ok(a > 0 && b > a, 'トークンの定義ブロックを切り出せない');
        css = css.slice(0, a) + css.slice(b);
        const raw = (css.match(/#[0-9A-Fa-f]{3,8}\b/g) || []).length;
        const rgba = (css.match(/rgba?\([0-9]/g) || []).length;
        // 2026-09-10 段階1 完了: 727 → 14。残り14はコメントと、インラインの style を拾う
        // 属性セレクタ (button[style*="background:#14161A"]) — 段階2でインラインを直すまで動かせない
        const LIMIT_HEX = 14, LIMIT_RGBA = 195;   // 段階3a: 線・輪郭のベールを --ink-rgb へ / 2026-10-03: 黒いカードの上の白ベールを --paper-rgb へ / 2026-10-29: ツアーの使われない「📍 タブを開いて試す」の CSS を消した
        assert.ok(raw <= LIMIT_HEX, `<style> の直値が増えている: ${raw} (上限 ${LIMIT_HEX})`);
        assert.ok(rgba <= LIMIT_RGBA, `<style> の rgba() が増えている: ${rgba} (上限 ${LIMIT_RGBA})`);
        if (raw < LIMIT_HEX - 20 || rgba < LIMIT_RGBA - 20) {
            assert.fail(`置き換えが進んだので上限を下げてください: hex ${raw} / rgba ${rgba}`);
        }
        // <style> の外 (インラインの style / JS のテンプレート文字列) も同じように見張る。
        // 2026-09-10 段階2 完了: 2340 → 614。残りは JS の色表・SVG の fill=/stroke=・
        // <meta theme-color> — 段階3 (グラフ・キャンバス) でまとめて扱う
        const outside = html.slice(0, s0) + html.slice(s1);
        const rawOut = (outside.match(/#[0-9A-Fa-f]{3,8}\b/g) || []).length;
        const LIMIT_INLINE = 281;   // 段階3d: 式の中の色もトークンへ (Codex指摘への対応)
        assert.ok(rawOut <= LIMIT_INLINE, `インラインの直値が増えている: ${rawOut} (上限 ${LIMIT_INLINE})`);
        if (rawOut < LIMIT_INLINE - 40) assert.fail(`置き換えが進んだので上限を下げてください: インライン ${rawOut}`);
    });
    test('★ --t-ink の塗りの上に、白固定の文字を置かない (ダークでは塗りが白に反転して消える — 2026-10-03 実機報告)', () => {
        // ★ --t-ink は「いちばん濃い文字色」だが塗り (黒いカード・主ボタン) にも使う。ダークでは白 (#F2F4F6) に反転するので、
        //   その上の文字は var(--card) / 薄い文字は var(--on-ink-soft) / ベールは rgba(var(--paper-rgb), …) でなければならない。
        //   var(--on-fill)・rgba(255,255,255,…)・#fff・white・var(--t-muted) は両テーマで同じ色 → 白地に白 (または薄灰) になる
        const html = _grRd('index.html').split(String.fromCharCode(13)).join('');
        const INK_FILL = /background(?:-color|-image)?\s*:\s*[^;"']*var\(--t-ink\)/;
        const WHITE_FIXED = /var\(--on-fill\)|rgba\(\s*255\s*,\s*255\s*,\s*255|#fff\b|#ffffff\b|color\s*:\s*white\b|var\(--t-(?:muted|body|strong)\)/i;
        const bad = [];
        // ① <style> のルール (トークンの定義ブロックは除く)
        const s0 = html.indexOf('<style'), s1 = html.lastIndexOf('</style>');
        let css = html.slice(s0, s1);
        const a = css.indexOf(':root, :root[data-theme="light"]'), b = css.indexOf('/* === マーブル');
        css = css.slice(0, a) + css.slice(b);
        for (const m of css.matchAll(/([^{}]+)\{([^{}]*)\}/g)) {
            const sel = m[1].trim().replace(/\s+/g, ' ').slice(-70), body = m[2];
            if ((INK_FILL.test(body) || /\.on-hero|\.dc-hero|\.has-combat/.test(sel)) && WHITE_FIXED.test(body)) bad.push(`CSS ${sel} → ${body.match(WHITE_FIXED)[0]}`);
        }
        // ② インラインの style 属性 / テンプレート文字列の style (同じ 1 つの style の中に 塗り と 文字 が同居するもの)
        for (const m of html.matchAll(/style="([^"]*)"/g)) {
            // テンプレートの中の三項 (`${on ? 'background:var(--t-ink);color:var(--card);' : 'background:var(--s2);color:var(--t-strong);'}`) は
            // 枝ごとに別の塗りなので、' で区切った断片ごとに見る (断片の中で 塗り と 文字 が同居するものだけ)
            for (const st of m[1].split("'")) {
                if (INK_FILL.test(st) && WHITE_FIXED.test(st)) bad.push(`inline (${html.slice(0, m.index).split('\n').length}行目) → ${st.match(WHITE_FIXED)[0]} on ${st.slice(0, 60)}`);
            }
        }
        // ③ 親が黒 (--t-ink) で、中の文字を別の要素・別の文字列で入れる箱: 中身に白固定が無いこと
        //   (テンプレート文字列全体を見ると、黒いボタンと無関係な添え字が同居するだけで引っかかるので、箱を名指しで見る)
        for (const [name, re] of [
            ['sbLoadErrorBanner', /b\.id = 'sbLoadErrorBanner';\s*b\.style\.cssText = '[^']*background:var\(--t-ink\)[^']*';\s*b\.innerHTML = `([^`]*)`/],
            ['mypageDmgAnalyzing', /id="mypageDmgAnalyzing" style="[^"]*background:var\(--t-ink\)[^"]*">([\s\S]*?)\n                <\/div>/],
            ['aiSpinOverlay', /o\.id = 'aiSpinOverlay';[\s\S]*?<div style="[^"]*background:var\(--t-ink\)[^"]*">([\s\S]*?)<\/div>`;/],
        ]) {
            const mm = html.match(re);
            assert.ok(mm, `${name} の箱を切り出せない (作りが変わったらこのテストも直す)`);
            if (WHITE_FIXED.test(mm[1])) bad.push(`${name} の中身 → ${mm[1].match(WHITE_FIXED)[0]}`);
        }
        assert.deepEqual(bad, [], `--t-ink の塗りの上に白固定の文字がある (ダークで消える):\n  ${bad.join('\n  ')}`);
        // ③ ヒーロー (黒いカード) の JS 側: 文字は var(--card)、ベールは rgba(var(--paper-rgb), …)
        assert.match(html, /const ink = hero \? 'var\(--card\)' : 'var\(--t-ink\)';/, 'ヒーローの見出しが白固定');
        assert.match(html, /const sub = hero \? 'rgba\(var\(--paper-rgb\), 0\.62\)' : 'var\(--t-body\)';/, 'ヒーローの説明が白固定');
        assert.match(html, /const sub = hero \? 'rgba\(var\(--paper-rgb\), 0\.55\)' : 'var\(--t-muted\)';/, 'ヒーローの 3 枠の添え字が白固定');
        assert.match(html, /color:var\(--hero-text-ops\);cursor:pointer;background:rgba\(var\(--paper-rgb\), 0\.08\);/, 'ヒーローの小ボタンの地が白固定');
        // 凸報告の「保存」: 塗りと一緒に文字色も決める (黒の上は --card / 緑の上は --ok-ink)
        assert.match(html, /btn\.style\.background = 'linear-gradient\(180deg,#1FC36E,#16A85D\)';\s*btn\.style\.color = 'var\(--ok-ink\)';/, '緑の保存ボタンの文字色を決めていない');
        assert.match(html, /btn\.style\.background = 'linear-gradient\(180deg,var\(--t-ink\),var\(--t-ink\)\)';\s*btn\.style\.color = 'var\(--card\)';/, '黒の保存ボタンの文字色を決めていない');
        // ④ 黒いカード用のトークン (ヒーローの紫・橙・緑の文字と線) は、テーマごとに違う値 (ライト = 黒の上の淡色 / ダーク = 白の上の濃色)
        const tokens = (block) => Object.fromEntries([...block.matchAll(/--(hero-(?:text|line)-\w+):\s*(#[0-9A-Fa-f]{6})/g)].map(x => [x[1], x[2].toUpperCase()]));
        const light = tokens(html.slice(html.indexOf(':root, :root[data-theme="light"]'), html.indexOf(':root[data-theme="dark"]')));
        const dark = tokens(html.slice(html.indexOf(':root[data-theme="dark"]'), html.indexOf('/* === マーブル')));
        assert.deepEqual(Object.keys(light).sort(), ['hero-line-ops', 'hero-line-warn', 'hero-text-ok', 'hero-text-ops', 'hero-text-warn']);
        assert.deepEqual(Object.keys(dark).sort(), Object.keys(light).sort(), 'ダークに無いヒーローのトークンがある');
        const lum = (hex) => { const c = [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16) / 255).map(v => v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)); return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]; };
        const contrast = (x, y) => { const [h, l] = [Math.max(lum(x), lum(y)), Math.min(lum(x), lum(y))]; return (h + 0.05) / (l + 0.05); };
        // ★ 文字が実際に載るのは、ヒーローの地そのものではなく 3 枠カードの半透明の地 (Codex指摘 2026-10-03):
        //   素の地 / 通常 (paper 0.07 のベール) / 🔒 固定 (紫 0.22) / 置けていない (橙 0.22) のすべてで 4.5:1 以上
        const mix = (base, rgb, a) => '#' + [0, 1, 2].map(i => Math.round(parseInt(base.slice(1 + 2 * i, 3 + 2 * i), 16) * (1 - a) + rgb[i] * a).toString(16).padStart(2, '0')).join('').toUpperCase();
        const surfaces = (hero, paper) => ({ 素: hero, 通常: mix(hero, paper, 0.07), 固定: mix(hero, [108, 66, 240], 0.22), 未達: mix(hero, [245, 158, 11], 0.22) });
        const onLight = surfaces('#14161A', [255, 255, 255]), onDark = surfaces('#F2F4F6', [23, 25, 29]);
        assert.deepEqual(Object.keys(onDark), ['素', '通常', '固定', '未達'], '合成の地 4 つすべてで測る (素の地だけだと半透明の地で届かない値を通す)');
        assert.match(html, /\.dc-plan-card\.on-hero\.fixed \{ border-color: var\(--hero-line-ops\); background: rgba\(108,66,240,0\.22\)\}/, '固定の枠のベールが変わった (テストの合成と合わせる)');
        assert.match(html, /\.dc-plan-card\.on-hero\.fixed\.unmet \{ border-color: var\(--hero-line-warn\); background: rgba\(245,158,11,0\.22\)\}/, '未達の枠のベールが変わった');
        assert.match(html, /\.dc-plan-card\.on-hero \{\s*background: rgba\(var\(--paper-rgb\), 0\.07\);/, '通常の枠のベールが変わった');
        for (const k of Object.keys(light)) {
            assert.notEqual(light[k], dark[k], `${k} が両テーマで同じ値 (ダークの白いカードの上で淡いまま)`);
            if (!k.startsWith('hero-text')) continue;
            for (const [name, bg] of Object.entries(onLight)) assert.ok(contrast(light[k], bg) >= 4.5, `${k} (ライト) が黒いヒーローの「${name}」の地で読めない: ${contrast(light[k], bg).toFixed(2)} on ${bg}`);
            for (const [name, bg] of Object.entries(onDark)) assert.ok(contrast(dark[k], bg) >= 4.5, `${k} (ダーク) が白いヒーローの「${name}」の地で読めない: ${contrast(dark[k], bg).toFixed(2)} on ${bg}`);
        }
    });
    test('🧱 2.5: 運営タブのサブタブ — カードはいつも同じタブ / 外すカード / 開いたときのタブ / 件数', () => {
        const L = globalThis.opsLayoutDomain;
        const byTab = (t) => L.CARDS.filter(c => c.tab === t).map(c => c.id);
        assert.deepEqual(L.TAB_KEYS, ['members', 'build', 'battle', 'master']);
        assert.deepEqual(byTab('members'), ['opsSecMembers', 'opsSecMockIntake', 'opsSecDiscord', 'opsSecPush'], '一斉通知は運営も使う (ユーザー決定) — 👥 メンバーに置く / Discord 用の文面も (2026-10-23)');
        assert.deepEqual(byTab('build'), ['opsSecReserve', 'opsSecPlan']);
        assert.deepEqual(byTab('battle'), ['opsSecBoss', 'opsSecFinish', 'opsSecAttackTap', 'opsSecAttackCheck'], '締め凸検索は戦況に残す (ユーザー決定) / S5: ✓ 凸の記録 は 結果の取り込み の前');
        assert.deepEqual(byTab('master'), ['opsSecSeason', 'opsSecBlocks', 'opsSecGrowth']);
        assert.deepEqual(L.CARDS.filter(c => c.tab === null).map(c => c.id).sort(),
            ['opsSecActions', 'opsSecCoord', 'opsSecPace', 'opsSecRecent', 'opsSecRemaining'], '画面から外すカードが違う');
        assert.ok(L.CARDS.every(c => c.tab === null || L.TAB_KEYS.includes(c.tab)), '知らないタブのカードがある');
        // 開いたときのタブ: 当日・終了 = 戦況 / それより前 = メンバー。記憶は同じ段階のあいだだけ・マスターでない人の 👑 は既定へ
        assert.deepEqual(['prep', 'pre', 'day', 'end'].map(L.defaultTab), ['members', 'members', 'battle', 'battle']);
        assert.equal(L.resolveTab(null, 'day', false), 'battle');
        assert.equal(L.resolveTab({ tab: 'build', stage: 'day' }, 'day', false), 'build');
        assert.equal(L.resolveTab({ tab: 'build', stage: 'pre' }, 'day', false), 'battle', '前日に選んだタブが当日も残る');
        assert.equal(L.resolveTab({ tab: 'master', stage: 'pre' }, 'pre', false), 'members', 'マスターでない人に 👑 を出した');
        assert.equal(L.resolveTab({ tab: 'master', stage: 'pre' }, 'pre', true), 'master');
        assert.equal(L.resolveTab({ tab: 'nope', stage: 'pre' }, 'pre', true), 'members');
        // タブの中のカードは既定で開く (自分で畳んだときだけ畳む)。従来の呼び方 (tabbed なし) は段階の既定のまま
        assert.equal(L.resolveOpen('opsSecPlan', 'day', {}, true, true), true);
        assert.equal(L.resolveOpen('opsSecPlan', 'day', { day: { opsSecPlan: false } }, true, true), false);
        assert.equal(L.resolveOpen('opsSecPlan', 'day', {}, true), false);
        assert.equal(L.STORAGE_KEY, 'shirisuko_ops_card_open_v2', '開閉の記憶を取り直していない (前の段階の畳みが残る)');
        // 件数: 未ロードは null (0 と混同させない)
        assert.deepEqual(L.tabCounts({}), { members: null, build: null, battle: null, master: null });
        assert.deepEqual(L.tabCounts({ mbRows: [{ todo: true }, { todo: false }, { todo: true }], reservations: { pending: 1, expired: 2 }, attackCounts: { total: 5, confirmed: 3, missing: 2 } }),
            { members: 2, build: 3, battle: 4, master: null });
        // S5: 予約を隠したシーズン (reservations.hidden) は 🧱 組む に予約の数を出さない / 結果の取り込みはタブの中でも畳んで始める (記憶があればそれ)
        assert.equal(L.tabCounts({ reservations: { hidden: true, pending: 3, expired: 1 } }).build, null);
        assert.equal(L.resolveOpen('opsSecAttackCheck', 'day', {}, true, true), false, '結果の取り込みを開いて始める');
        assert.equal(L.resolveOpen('opsSecAttackCheck', 'day', { day: { opsSecAttackCheck: true } }, true, true), true, '開いた記憶を無視した');
        assert.equal(L.resolveOpen('opsSecAttackTap', 'day', {}, true, true), true);
    });
    test('★ 実行 (2.5): _applyOpsTabCards — そのタブのカードだけ本文へ・ほかと外したカードは置き場へ / 👑 だけ「その他」を出す', () => {
        const html = _fs2b.readFileSync(new URL('../index.html', import.meta.url), 'utf8').replace(/\r\n/g, '\n');
        const src = html.match(/function _applyOpsTabCards\(tab\) \{[\s\S]*?\n        \}\n/)?.[0];
        assert.ok(src, '_applyOpsTabCards が無い');
        const L = globalThis.opsLayoutDomain;
        const mk = (id) => ({ id, where: 'start', classList: { set: new Set(), toggle(c, on) { on ? this.set.add(c) : this.set.delete(c); } }, style: {} });
        const els = Object.fromEntries([...L.CARDS.map(c => c.id), 'opsTabHold', 'opsEtc', 'opsHomeCrosslink'].map(id => [id, mk(id)]));
        const hold = els.opsTabHold, anchor = els.opsEtc;
        hold.appendChild = (el) => { el.where = 'hold'; };
        anchor.insertAdjacentElement = (_pos, el) => { el.where = 'body'; };
        let etcOpened = 0;
        const run = new Function('window', 'document', '_setOpsEtcOpen', `${src}\nreturn _applyOpsTabCards;`)(
            { opsLayoutDomain: L }, { getElementById: (id) => els[id] || null }, () => { etcOpened++; });
        for (const tab of L.TAB_KEYS) {
            run(tab);
            const body = L.CARDS.filter(c => els[c.id].where === 'body').map(c => c.id);
            assert.deepEqual(body, L.CARDS.filter(c => c.tab === tab).map(c => c.id), `${tab}: 本文に出すカードが違う`);
            assert.equal(anchor.style.display, tab === 'master' ? '' : 'none', `${tab}: 「その他」の出し方が違う`);
            assert.equal(anchor.classList.set.has('as-master'), tab === 'master');
            assert.equal(els.opsHomeCrosslink.where, 'hold', 'メンバー向けの導線を運営の画面に出した');
        }
        assert.equal(etcOpened, 1, '👑 のときだけ「その他」を開く');
        assert.ok(L.CARDS.filter(c => c.tab === null).every(c => els[c.id].where === 'hold'), '外したカードが本文に出た');
    });
