        assert.ok(/if \(!me && typeof window\.supabaseLoadAllPlayers === 'function'\) me = \(\(await window\.supabaseLoadAllPlayers\(true\)\) \|\| \[\]\)\.find\(p => p\.name === name\) \|\| null;/.test(lm), '書庫の人の模擬を引けない');
        // ふるり値試算: B でも桁でも
