        assert.ok(/const damage = formatDomain\.parseDamageInput\(dmgInput \? dmgInput\.value : ''\);/.test(html) && /const v = formatDomain\.parseDamageInput\(dmgInput\.value\);/.test(html), 'ふるり値試算の読み方が formatDomain.parseDamageInput でない');
