        assert.ok(/_rrAptView = v === 'bars' \? 'bars' : 'scatter';/.test(sv) && /localStorage\.setItem\('shirisuko_rr_apt_v1'/.test(sv) && /_rrPaintAptitude\(_rrLastApt\)/.test(sv), '切り替えの作りが違う');
        // HP表の読み込みは失敗を覚えない (次に再試行する)
