    test('★ parseOpenid: アドレスの openid は base64 で包まれている (生の数字を期待すると1件も読めない)', () => {
        // しりすこスクワッド personal-scan.ts が実機で確かめた形。これが読めないと名寄せが成立しない
        const wrapped = Buffer.from('123456789', 'utf8').toString('base64');   // 'MTIzNDU2Nzg5'
        assert.equal(dom.parseOpenid(`https://www.blablalink.com/user?openid=${wrapped}`), '123456789');
        assert.equal(dom.parseOpenid(`https://www.blablalink.com/ja/user?openid=${wrapped}&from=union`), '123456789');
        assert.equal(dom.parseOpenid(wrapped), '123456789', '値だけ貼られた場合も受ける');
        // URL-safe base64 (- と _) / %xx で包まれている場合
        const urlSafe = Buffer.from('nikke:987654321', 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_');
        assert.equal(dom.parseOpenid(`https://x/user?openid=${urlSafe}`), '987654321');
        // 末尾に = の付く base64 は URL では %3D になる
        const padded = Buffer.from('12345678', 'utf8').toString('base64');   // 'MTIzNDU2Nzg='
        assert.equal(dom.parseOpenid(`https://x/user?openid=${encodeURIComponent(padded)}`), '12345678');
        // 包まれていない (生の数字) 場合も従来どおり読める
        assert.equal(dom.parseOpenid('123456789'), '123456789');
        assert.equal(dom.parseOpenid('  123456789  '), '123456789');
        assert.equal(dom.parseOpenid('https://www.blablalink.com/profile?uid=123456789'), '123456789');
        assert.equal(dom.parseOpenid('https://x/y?a=1&openid=987654321&b=2'), '987654321');
        assert.equal(dom.parseOpenid('https://x/y#intl_open_id=555555555'), '555555555');
        // ★ 取り違えは「他人の育成が別人に付く」事故。関係ない数字を拾わないこと
        assert.equal(dom.parseOpenid('https://x/y?area=81&t=1725792000000'), null, '別のパラメータを識別子にしている');
        assert.equal(dom.parseOpenid('12345'), null, '短すぎる数字を通している');
        assert.equal(dom.parseOpenid('abc123456'), null, 'base64 として開けない文字列から数字を拾っている');
        assert.equal(dom.parseOpenid('テスト123456'), null);
        assert.equal(dom.parseOpenid('abc'), null);
        assert.equal(dom.parseOpenid(''), null);
        assert.equal(dom.parseOpenid(null), null);
    });

    test('★ wantedCodesFor: 使われたキャラ → name_code。対応表に無い名前は missing に出す (黙って外さない)', () => {
        const map = { '1012': { jp: 'サクラ', pad: 'サクラ' }, '3015': { jp: 'サクラ', pad: '鈴原サクラ' }, '1007': { jp: 'D', pad: 'D' } };
        const r = dom.wantedCodesFor(['鈴原サクラ', 'D', 'シフティー', 'D'], map);
        assert.deepEqual(r.codes, [1007, 3015], '重複を畳んで昇順にしていない');
        assert.deepEqual(r.missing, ['シフティー'], '対応表に無い名前を黙って外している');
        assert.deepEqual(dom.wantedCodesFor([], map), { codes: [], missing: [] });
        assert.deepEqual(dom.wantedCodesFor(['D'], null), { codes: [], missing: ['D'] });
        // pad が無い行 (CDN にしか無いキャラ) は対応先にしない
        assert.deepEqual(dom.wantedCodesFor(['謎'], { '9999': { jp: '謎', pad: null } }).missing, ['謎']);
    });

    test('★ importSummary: 取れた/非公開/未ひも付け/失敗 を分け、取れなかった人をまとめる', () => {
        const r = dom.importSummary([
            { name: 'a', status: 'ok', count: 5 }, { name: 'b', status: 'ok', count: 3 },
            { name: 'c', status: 'private' }, { name: 'd', status: 'no_openid' },
            { name: 'e', status: 'error' }, { name: 'f', status: 'なにこれ' },
        ]);
        assert.equal(r.ok, 2); assert.equal(r.characters, 8);
        assert.equal(r.private, 1); assert.equal(r.noOpenid, 1);
        assert.equal(r.error, 2, '知らない状態を失敗に寄せていない');
        assert.deepEqual(r.failed.map(x => x.name), ['c', 'd', 'e', 'f']);
        const none = dom.importSummary(null);
        assert.equal(none.ok, 0); assert.equal(none.characters, 0); assert.deepEqual(none.failed, []);
    });

    test('★ 案内 (ヘルプ・ツアー) が 🧱 ブロック制 (2026-10-23) の画面に合っている: 目次と章が一致 / メンバー向けと運営向けの両方 / ツアー 10 ステップ', () => {
        const html = _grRd('index.html').split(String.fromCharCode(13)).join('');
        // 目次のリンク先が全部ある / 章のぶんだけ目次がある (章を足したら目次も足す)
        const toc = html.match(/<aside class="help-toc" id="helpToc">[\s\S]*?<\/aside>/)?.[0] || '';
        const links = [...toc.matchAll(/href="#(help-[a-z-]+)"/g)].map(m => m[1]);
        const ids = [...html.matchAll(/<section id="(help-[a-z-]+)" class="help-section">/g)].map(m => m[1]);
        assert.deepEqual(links, ids, '目次と章の並びが一致していない');
        assert.equal(ids.length, 18, '章の数が 18 でない');
        // 2026-09 に入ったものが章になっている (予約 / 本人向けのプランの読み方 / 運営向けの算出 / 分析)
        for (const id of ['help-reserve', 'help-plan', 'help-plan-ops', 'help-analysis', 'help-ops']) assert.ok(ids.includes(id), id + ' が無い');
        // 本文中の #help- リンクも切れていない (FAQ からの参照など)
        const refs = [...html.matchAll(/href="#(help-[a-z-]+)"/g)].map(m => m[1]);
        for (const r of refs) assert.ok(ids.includes(r), '切れたリンク: #' + r);
        // メンバー向けと運営向けの両方 (ユーザー決定 2026-09-15)
        const helpBody = html.slice(html.indexOf('<section id="help-overview"'), html.indexOf('<section id="help-faq"'));
        assert.ok((helpBody.match(/<span class="help-pill">メンバー<\/span>/g) || []).length >= 5, 'メンバー向けの章が少ない');
        assert.ok((helpBody.match(/<span class="help-pill">運営<\/span>/g) || []).length >= 5, '運営向けの章が少ない');
        // 今の画面の言葉で書かれている (古い名前が残っていない)
        for (const word of ['今期の確認', 'ユニオンレイド参加可能時間', '枠を予約する', '🔒 予約', '📌', '仮置き', '何凸するか', '📅 きょうの凸', '📘 登録された模擬', 'Discord に貼', '🧮 この条件で算出', '📥 結果の取り込み', '⏰ 結果がまだの凸',
            '🧱 盤', '締め凸検索', '✓ 凸の記録', '📅 レイド予定表', 'みんなの模擬', '凸プランを組む', '👑 マスター', '育成くらべ', '逆引き', 'GB比較', 'サイドバー', 'ライト / ダーク', '未取り込みの人だけ', '✅ 確認しました', '組み直し中', 'ボス 5 の弱点の模擬を 2 編成']) {
            assert.ok(helpBody.includes(word), 'ヘルプに「' + word + '」が無い');
        }
        for (const old of ['現在凸可能のみ', '全員で算出', '画面右上の', '2つのモード', '模擬提出チェック', '前回ダメージ引継ぎは廃止',
            '5つのタブ', '模擬タブ', '⏳ 隙間', '隙間時間型', '戦闘準備', '⚔️ 凸報告', '凸を報告する ▶', '締め凸の依頼', '依頼への返事', '締め凸コンソール', '📈 消化のペース', '🔁 直近の動き', '🧹 整理', '残り戦闘可能メンバー',
            // 用語集 (docs/用語集.md・2026-10-23 ユーザー決定) の「使わない言い方」
            '戦闘可能時間', '出られる時間', '締凸検索', '締め凸候補検索', '申請', '引き受けた凸', '🎯 あなたの3凸', '📣 お願い', '📌 固定', '運営の固定', '🔒 予約で固定',
            // S5 (用語集): メンバーは ✓ を押さない・決定し直すのは組み直したブロックだけ・予約の通知は従来の画面だけ (S5 レビュー DX-9 / DX-6 / RS-5)
            '✓ 凸しました', '前回の配信を尊重', '予約の承認 はここに届きます', 'ブロックで配信された「あなたの凸」']) {
            assert.ok(!helpBody.includes(old), 'ヘルプに古い言葉「' + old + '」が残っている');
        }
        // ツアー: 配列を実際に評価する (文字列の検査ではなく、壊れた JS なら落ちる)
        const src = html.match(/const TOUR_STEPS = \[[\s\S]*?\n        \];/)?.[0] || '';
        assert.ok(src, 'TOUR_STEPS が無い');
        const steps = new Function(src + '\nreturn TOUR_STEPS;')();
        assert.equal(steps.length, 10, 'ツアーが 10 ステップでない');
        for (const [i, st] of steps.entries()) {
            for (const k of ['emoji', 'chapterTag', 'stepLabel', 'title', 'body', 'tip', 'accentColor', 'accentDark']) assert.ok(st[k], 'ステップ ' + (i + 1) + ' に ' + k + ' が無い');
            assert.equal(st.stepLabel, 'CHAPTER ' + String(i + 1).padStart(2, '0'), 'CHAPTER の番号がずれている');
            if (st.demo) assert.ok(['avail', 'battle'].includes(st.demo), '知らないデモ: ' + st.demo);
        }
        assert.deepEqual(steps.filter(s => s.demo).map(s => s.demo), ['avail', 'battle'], '体験デモの並び (時間 → 凸) が崩れている (2026-10-22: 模擬は Discord なのでデモなし)');
        assert.ok(steps[0].body.includes('8つのステップ'), '冒頭の案内がステップ数と合っていない');
        // ツアーも用語集 (docs/用語集.md) の「使わない言い方」を出さない
        const tourText = steps.map(st => [st.chapterTag, st.title, st.body, st.tip].join(' ')).join(' ');
        for (const old of ['戦闘可能時間', '出られる時間', '締凸検索', '申請', '引き受けた凸', 'あなたの3凸', '📣 お願い', '📌 固定', '模擬タブ', '戦闘に入る', '✓ 凸しました', '予約の承認']) {   // S5: メンバーは ✓ を押さない・予約の通知は来ない (S5 レビュー DX-9 / RS-5)
            assert.ok(!tourText.includes(old), 'ツアーに古い言葉「' + old + '」が残っている');
        }
        const head = (s) => s.chapterTag + ' ' + s.title;
        assert.ok(steps.some(s => /予約/.test(head(s))) && steps.some(s => /運営担当/.test(head(s))) && steps.some(s => /こう決まる/.test(head(s))), '予約 / 運営 / 3凸 の章が無い');
        // 足したステップの色はトークン (直値の上限に数えない)。既存 7 ステップの hex は上限の内訳に入っている
        assert.ok([4, 7, 8].every(i => /^var\(--/.test(steps[i].accentColor) && /^var\(--/.test(steps[i].accentDark)), '足したステップ (予約 / 運営 / 分析) の色が直値');
        // ★ 体験デモは手描きの見本ではなく、練習モード (本物の画面) の該当する課題への入口 (2026-10-03)。demo の名前 → 練習の課題の key
        assert.ok(!/function _tourDemo(Avail|Mock|Battle)Body\(/.test(html), '手描きの体験デモが残っている (本番の画面を直すたびにずれる)');
        const map = new Function(html.match(/const TOUR_DEMO_START = (\{[^}]*\});/)[1].replace(/^/, 'return ') )();
        assert.deepEqual(Object.keys(map), ['avail', 'battle']);
        assert.deepEqual(Object.values(map).map(v => v[0]), ['discord', 'report'], 'ツアーのデモから入る練習の課題がずれている (2026-10-24 🗣 9f: 前日は Discord に書くだけ)');
        assert.match(html, /function _tourDemoHtml\(kind\)[\s\S]*?onclick="startPractice\('member', '\$\{d\[0\]\}'\)"/, '体験デモが練習モードへの入口でない');
        assert.match(html, /\$\{step\.demo \? _tourDemoHtml\(step\.demo\) : ''\}/, 'ツアーがデモの種類を渡していない');
    });

