            assert.deepEqual(rn.unseen(notes, null, Date.parse('2026-12-01T00:00:00Z')), [], '古い項目しか無いのに初めての端末に出している');
            assert.equal(rn.latestId(notes), 2026100801); assert.equal(rn.latestId([]), null);
